1	/**
2	 * Generated-file detection for symbol-disambiguation down-ranking.
3	 *
4	 * When a query like "Send" matches 17 symbols across protobuf scaffolding,
5	 * test mocks, and the hand-written implementation, the FTS ranker often
6	 * surfaces the generated stubs first because their names are identical
7	 * to the implementation's name (validated empirically on cosmos-sdk —
8	 * see project_go_multi_module_audit memory). Generated stubs frequently
9	 * have no body to trace from, so the agent ends up reading source anyway.
10	 *
11	 * This helper is a pure path-based classifier consulted at disambiguation
12	 * time (findSymbol / findAllSymbols / codegraph_search formatting), NOT
13	 * a hard filter — generated nodes are still in the graph and remain
14	 * reachable; they just rank LAST when there's a real implementation
15	 * with the same name.
16	 *
17	 * Scope: suffix patterns only. Most generated files follow the
18	 * `<basename>.<tool>.<ext>` convention (`.pb.go`, `_grpc.pb.go`,
19	 * `.g.dart`, `_pb2.py`), and that covers ~all of what we saw in the
20	 * Go audit. A future addition would be scanning for the canonical
21	 * `// Code generated by` header during extraction, for the rare files
22	 * that defy the suffix convention.
23	 */
24	
25	const GENERATED_PATTERNS: ReadonlyArray<RegExp> = [
26	  // Go — protobuf / gRPC / pulsar
27	  /\.pb\.go$/,
28	  /\.pulsar\.go$/,
29	  /_grpc\.pb\.go$/,
30	  // Go — mockgen output. Default emits `mock_<src>.go`; many projects
31	  // (cosmos-sdk uses `expected_*_mocks.go`) rename to `*_mock.go` /
32	  // `*_mocks.go`. Matching either suffix catches both conventions
33	  // without false-positive risk on hand-written sources.
34	  /_mock\.go$/,
35	  /_mocks\.go$/,
36	  /^mock_[^/]+\.go$/,
37	  // TypeScript / JavaScript — common codegen suffixes (Apollo / GraphQL
38	  // codegen, Prisma, Hasura, ts-proto, gRPC-web, swagger-codegen).
39	  /\.generated\.[jt]sx?$/,
40	  /\.gen\.[jt]sx?$/,
41	  /\.pb\.[jt]s$/,
42	  /_pb\.[jt]s$/,
43	  /_grpc_pb\.[jt]s$/,
44	  // Minified bundles vendored into a repo (docs sites, examples). Their
45	  // single-letter symbols make name-based edges pure noise.
46	  /\.min\.m?js$/,
47	  // Python — protobuf / gRPC / openapi-codegen
48	  /_pb2(_grpc)?\.py$/,
49	  /_pb2\.pyi$/,
50	  // C++ — protobuf
51	  /\.pb\.(cc|h)$/,
52	  // C# — protobuf / gRPC (protoc-gen-csharp puts output under obj/ but
53	  // many projects also commit *.g.cs and *Grpc.cs siblings)
54	  /\.g\.cs$/,
55	  /Grpc\.cs$/,
56	  // Java — protobuf / gRPC: protoc-gen-java emits `*OuterClass.java`,
57	  // protoc-gen-grpc-java emits `*Grpc.java`. The XxxImplBase abstract
58	  // class lives inside Xxx*Grpc.java.
59	  /OuterClass\.java$/,
60	  /Grpc\.java$/,
61	  // Swift — protobuf
62	  /\.pb\.swift$/,
63	  // Dart — build_runner / freezed / json_serializable / chopper
64	  /\.g\.dart$/,
65	  /\.freezed\.dart$/,
66	  /\.pb\.dart$/,
67	  /\.pbgrpc\.dart$/,
68	  /\.chopper\.dart$/,
69	  // Rust — common build.rs OUT_DIR outputs are usually outside the source
70	  // tree, but in-tree generated files often use `*.generated.rs`.
71	  /\.generated\.rs$/,
72	];
73	
74	/**
75	 * Whether `filePath` looks like a tool-generated source file based on
76	 * its filename. Path-only — does not read content. The result is a
77	 * relevance hint for disambiguation, not a hard claim.
78	 */
79	export function isGeneratedFile(filePath: string): boolean {
80	  return GENERATED_PATTERNS.some((p) => p.test(filePath));
81	}
