517	  /**
518	   * Names whose segments cover at least `minWords` distinct PROMPT WORDS —
519	   * the co-occurrence probe behind the prompt hook's medium tier: the words
520	   * "state" and "machine" both being segments of `OrderStateMachine` is strong
521	   * evidence the prompt names that symbol in prose. Ordered by coverage.
522	   *
523	   * Takes (segment variant → original word) pairs and folds variants back to
524	   * their word INSIDE the SQL: a name matching both `service` and `services`
525	   * counts ONE word, not two. Counting raw variants let plural-variant pairs
526	   * of a single word tie with genuine two-word matches and — because ORDER
527	   * BY/LIMIT run here, before any JS-side re-check — crowd a real match past
528	   * the LIMIT on vocab-heavy repos (#1146).
529	   */
530	  getSegmentCoOccurrence(
531	    variants: Array<{ segment: string; word: string }>,
532	    minWords: number,
533	    limit: number,
534	  ): Array<{ name: string; matches: number }> {
535	    if (variants.length === 0) return [];
536	    const placeholders = variants.map(() => '?').join(', ');
537	    const whens = variants.map(() => 'WHEN ? THEN ?').join(' ');
538	    const rows = this.db
539	      .prepare(
540	        `SELECT name, COUNT(DISTINCT CASE segment ${whens} END) AS matches
541	         FROM name_segment_vocab
542	         WHERE segment IN (${placeholders})
543	         GROUP BY name
544	         HAVING matches >= ?
545	         ORDER BY matches DESC, length(name) ASC
546	         LIMIT ?`,
547	      )
548	      .all(
549	        ...variants.flatMap((v) => [v.segment, v.word]),
550	        ...variants.map((v) => v.segment),
551	        minWords,
552	        limit,
553	      ) as Array<{ name: string; matches: number }>;
554	    return rows;
555	  }
