557	  /** How many distinct names each segment appears in — the rarity signal that
558	   *  separates a discriminative word ("checkout") from a ubiquitous one ("state"). */
559	  getSegmentNameCounts(segments: string[]): Map<string, number> {
560	    if (segments.length === 0) return new Map();
561	    const placeholders = segments.map(() => '?').join(', ');
562	    const rows = this.db
563	      .prepare(
564	        `SELECT segment, COUNT(*) AS n FROM name_segment_vocab
565	         WHERE segment IN (${placeholders}) GROUP BY segment`,
566	      )
567	      .all(...segments) as Array<{ segment: string; n: number }>;
568	    return new Map(rows.map((r) => [r.segment, r.n]));
569	  }
