579	  /**
580	   * Get a node by ID
581	   */
582	  getNodeById(id: string): Node | null {
583	    // Check cache first
584	    if (this.nodeCache.has(id)) {
585	      const cached = this.nodeCache.get(id)!;
586	      // Move to end to implement LRU (delete and re-add)
587	      this.nodeCache.delete(id);
588	      this.nodeCache.set(id, cached);
589	      return cached;
590	    }
591	
592	    if (!this.stmts.getNodeById) {
593	      this.stmts.getNodeById = this.db.prepare('SELECT * FROM nodes WHERE id = ?');
594	    }
595	    const row = this.stmts.getNodeById.get(id) as NodeRow | undefined;
596	    if (!row) {
597	      return null;
598	    }
599	
600	    const node = rowToNode(row);
601	    this.cacheNode(node);
602	    return node;
603	  }
604	
605	  /**
606	   * Batch lookup: fetch many nodes by ID in a single SQL round-trip.
607	   *
608	   * Replaces the N+1 pattern in graph traversal where every edge would
609	   * trigger its own `getNodeById` call. For a function with 50 callers
610	   * this collapses 50 point reads into one IN-list query (~10-50x
611	   * faster end-to-end).
612	   *
613	   * Returns a Map keyed by id so callers can preserve their own ordering
614	   * (typically the order edges were returned from the graph). Missing IDs
615	   * are simply absent from the map.
616	   *
617	   * Cache-aware: ids already in the LRU cache are served from memory and
618	   * the SQL query only touches the misses.
619	   */
620	  getNodesByIds(ids: readonly string[]): Map<string, Node> {
621	    const out = new Map<string, Node>();
622	    if (ids.length === 0) return out;
623	
624	    // Serve cache hits first; build the miss list for SQL.
625	    const misses: string[] = [];
626	    for (const id of ids) {
627	      const cached = this.nodeCache.get(id);
628	      if (cached !== undefined) {
629	        // LRU touch
630	        this.nodeCache.delete(id);
631	        this.nodeCache.set(id, cached);
632	        out.set(id, cached);
633	      } else {
634	        misses.push(id);
635	      }
636	    }
637	    if (misses.length === 0) return out;
638	
639	    // Chunk under SQLite's parameter limit (default 999, raised to 32766
640	    // in better-sqlite3 builds — chunk at 500 for safety across both
641	    // backends and to keep the query plan simple).
642	    for (let i = 0; i < misses.length; i += SQLITE_PARAM_CHUNK_SIZE) {
643	      const chunk = misses.slice(i, i + SQLITE_PARAM_CHUNK_SIZE);
644	      const placeholders = chunk.map(() => '?').join(',');
645	      const rows = this.db
646	        .prepare(`SELECT * FROM nodes WHERE id IN (${placeholders})`)
647	        .all(...chunk) as NodeRow[];
648	      for (const row of rows) {
649	        const node = rowToNode(row);
650	        out.set(node.id, node);
651	        this.cacheNode(node);
652	      }
653	    }
654	    return out;
655	  }
656	
657	  private getExistingNodeIds(ids: readonly string[]): Set<string> {
658	    const out = new Set<string>();
659	    if (ids.length === 0) return out;
660	
661	    const uniqueIds = [...new Set(ids)];
662	    for (let i = 0; i < uniqueIds.length; i += SQLITE_PARAM_CHUNK_SIZE) {
663	      const chunk = uniqueIds.slice(i, i + SQLITE_PARAM_CHUNK_SIZE);
664	      const placeholders = chunk.map(() => '?').join(',');
665	      const rows = this.db
666	        .prepare(`SELECT id FROM nodes WHERE id IN (${placeholders})`)
667	        .all(...chunk) as { id: string }[];
668	      for (const row of rows) {
669	        out.add(row.id);
670	      }
671	    }
672	
673	    return out;
674	  }
