676	  /**
677	   * Add a node to the cache, evicting oldest if needed
678	   */
679	  private cacheNode(node: Node): void {
680	    if (this.nodeCache.size >= this.maxCacheSize) {
681	      // Evict oldest (first) entry
682	      const firstKey = this.nodeCache.keys().next().value;
683	      if (firstKey) {
684	        this.nodeCache.delete(firstKey);
685	      }
686	    }
687	    this.nodeCache.set(node.id, node);
688	  }
