910	      "SELECT * FROM nodes WHERE language = ? AND decorators LIKE '%' || ? || '%'"
911	    );
912	    for (const row of stmt.iterate(language, `"${decorator}"`)) {
913	      yield rowToNode(row as NodeRow);
