1106	  /**
1107	   * Match-everything path used when the user supplied only field
1108	   * filters (`kind:function lang:typescript`) with no text. Returns
1109	   * candidates ordered by name; the caller's filter pass narrows to
1110	   * what was asked for.
1111	   */
1112	  private searchAllByFilters(options: {
1113	    kinds?: NodeKind[];
1114	    languages?: Language[];
1115	    limit: number;
1116	  }): SearchResult[] {
1117	    const { kinds, languages, limit } = options;
1118	    let sql = 'SELECT * FROM nodes WHERE 1=1';
1119	    const params: (string | number)[] = [];
1120	    if (kinds && kinds.length > 0) {
1121	      sql += ` AND kind IN (${kinds.map(() => '?').join(',')})`;
1122	      params.push(...kinds);
1123	    }
1124	    if (languages && languages.length > 0) {
1125	      sql += ` AND language IN (${languages.map(() => '?').join(',')})`;
1126	      params.push(...languages);
1127	    }
1128	    sql += ' ORDER BY name LIMIT ?';
1129	    params.push(limit);
1130	    const rows = this.db.prepare(sql).all(...params) as NodeRow[];
1131	    return rows.map((row) => ({ node: rowToNode(row), score: 1 }));
1132	  }
