1266	  /**
1267	   * LIKE-based substring search for cases where FTS doesn't match
1268	   * Useful for camelCase matching (e.g., "signIn" finds "signInWithGoogle")
1269	   */
1270	  private searchNodesLike(query: string, options: SearchOptions): SearchResult[] {
1271	    const { kinds, languages, limit = 100, offset = 0 } = options;
1272	
1273	    let sql = `
1274	      SELECT nodes.*,
1275	        CASE
1276	          WHEN name = ? THEN 1.0
1277	          WHEN name LIKE ? THEN 0.9
1278	          WHEN name LIKE ? THEN 0.8
1279	          WHEN qualified_name LIKE ? THEN 0.7
1280	          ELSE 0.5
1281	        END as score
1282	      FROM nodes
1283	      WHERE (
1284	        name LIKE ? OR
1285	        qualified_name LIKE ? OR
1286	        name LIKE ?
1287	      )
1288	    `;
1289	
1290	    // Pattern variants for better matching
1291	    const exactMatch = query;
1292	    const startsWith = `${query}%`;
1293	    const contains = `%${query}%`;
1294	
1295	    const params: (string | number)[] = [
1296	      exactMatch,     // Exact match score
1297	      startsWith,     // Starts with score
1298	      contains,       // Contains score
1299	      contains,       // Qualified name score
1300	      contains,       // WHERE: name contains
1301	      contains,       // WHERE: qualified_name contains
1302	      startsWith,     // WHERE: name starts with
1303	    ];
1304	
1305	    if (kinds && kinds.length > 0) {
1306	      sql += ` AND kind IN (${kinds.map(() => '?').join(',')})`;
1307	      params.push(...kinds);
1308	    }
1309	
1310	    if (languages && languages.length > 0) {
1311	      sql += ` AND language IN (${languages.map(() => '?').join(',')})`;
1312	      params.push(...languages);
1313	    }
1314	
1315	    sql += ' ORDER BY score DESC, length(name) ASC LIMIT ? OFFSET ?';
1316	    params.push(limit, offset);
1317	
1318	    const rows = this.db.prepare(sql).all(...params) as (NodeRow & { score: number })[];
1319	
1320	    return rows.map((row) => ({
1321	      node: rowToNode(row),
1322	      score: row.score,
1323	    }));
1324	  }
