1326	  /**
1327	   * Find nodes by exact name match
1328	   *
1329	   * Used for hybrid search - looks up symbols by exact name or case-insensitive match.
1330	   * Returns high-confidence matches for known symbol names extracted from query.
1331	   *
1332	   * @param names - Array of symbol names to look up
1333	   * @param options - Search options (kinds, languages, limit)
1334	   * @returns SearchResult array with exact matches scored at 1.0
1335	   */
1336	  findNodesByExactName(names: string[], options: SearchOptions = {}): SearchResult[] {
1337	    if (names.length === 0) return [];
1338	
1339	    const { kinds, languages, limit = 50 } = options;
1340	
1341	    // Two-pass approach to handle common names (e.g., "run" has 40+ matches):
1342	    // Pass 1: Find which files contain distinctive (rare) symbols from the query.
1343	    // Pass 2: Query each name, boosting results that co-locate with distinctive symbols.
1344	
1345	    // Pass 1: Find files containing each queried name, identify distinctive names
1346	    const nameToFiles = new Map<string, Set<string>>();
1347	    for (const name of names) {
1348	      let sql = 'SELECT DISTINCT file_path FROM nodes WHERE name COLLATE NOCASE = ?';
1349	      const params: (string | number)[] = [name];
1350	      if (kinds && kinds.length > 0) {
1351	        sql += ` AND kind IN (${kinds.map(() => '?').join(',')})`;
1352	        params.push(...kinds);
1353	      }
1354	      sql += ' LIMIT 100';
1355	      const rows = this.db.prepare(sql).all(...params) as { file_path: string }[];
1356	      nameToFiles.set(name.toLowerCase(), new Set(rows.map(r => r.file_path)));
1357	    }
1358	
1359	    // Distinctive names are those with fewer than 10 file matches (e.g., "scrapeLoop" = 1 file)
1360	    const distinctiveFiles = new Set<string>();
1361	    for (const [, files] of nameToFiles) {
1362	      if (files.size > 0 && files.size < 10) {
1363	        for (const f of files) distinctiveFiles.add(f);
1364	      }
1365	    }
1366	
1367	    // Pass 2: Query each name with per-name limit, scoring by co-location
1368	    const perNameLimit = Math.max(8, Math.ceil(limit / names.length));
1369	    const allResults: SearchResult[] = [];
1370	    const seenIds = new Set<string>();
1371	
1372	    for (const name of names) {
1373	      let sql = `
1374	        SELECT nodes.*, 1.0 as score
1375	        FROM nodes
1376	        WHERE name COLLATE NOCASE = ?
1377	      `;
1378	      const params: (string | number)[] = [name];
1379	
1380	      if (kinds && kinds.length > 0) {
1381	        sql += ` AND kind IN (${kinds.map(() => '?').join(',')})`;
1382	        params.push(...kinds);
1383	      }
1384	
1385	      if (languages && languages.length > 0) {
1386	        sql += ` AND language IN (${languages.map(() => '?').join(',')})`;
1387	        params.push(...languages);
1388	      }
1389	
1390	      // Fetch enough to find co-located results among common names
1391	      sql += ' LIMIT ?';
1392	      params.push(Math.max(perNameLimit * 3, 50));
1393	
1394	      const rows = this.db.prepare(sql).all(...params) as (NodeRow & { score: number })[];
1395	      const nameResults: SearchResult[] = [];
1396	      for (const row of rows) {
1397	        const node = rowToNode(row);
1398	        if (seenIds.has(node.id)) continue;
1399	        // Boost results in files that also contain distinctive symbols
1400	        const coLocationBoost = distinctiveFiles.has(node.filePath) ? 20 : 0;
1401	        nameResults.push({ node, score: row.score + coLocationBoost });
1402	      }
1403	
1404	      // Sort by score (co-located first), take per-name limit
1405	      nameResults.sort((a, b) => b.score - a.score);
1406	      for (const r of nameResults.slice(0, perNameLimit)) {
1407	        seenIds.add(r.node.id);
1408	        allResults.push(r);
1409	      }
1410	    }
1411	
1412	    // Sort all results by score so co-located results bubble up
1413	    allResults.sort((a, b) => b.score - a.score);
1414	    return allResults.slice(0, limit);
1415	  }
