1489	  /**
1490	   * Insert multiple edges in a transaction
1491	   */
1492	  insertEdges(edges: Edge[]): void {
1493	    if (edges.length === 0) return;
1494	
1495	    this.db.transaction(() => {
1496	      const endpointIds = new Set<string>();
1497	      for (const edge of edges) {
1498	        endpointIds.add(edge.source);
1499	        endpointIds.add(edge.target);
1500	      }
1501	      const existingNodeIds = this.getExistingNodeIds([...endpointIds]);
1502	
1503	      for (const edge of edges) {
1504	        if (!existingNodeIds.has(edge.source) || !existingNodeIds.has(edge.target)) {
1505	          continue;
1506	        }
1507	        this.insertEdge(edge);
1508	      }
1509	    })();
1510	  }
