1634	  /**
1635	   * Cross-file edges whose TARGET is a node in `filePath` and whose SOURCE is a
1636	   * node in a *different* file, paired with the target node's (name, kind) so a
1637	   * caller can re-resolve the edge to the re-indexed target's new ID (node IDs
1638	   * are `sha256(filePath:kind:name:line)`, so any line shift in the callee file
1639	   * changes target IDs and a naive re-insert by old ID silently drops them).
1640	   * Used by `storeExtractionResult` to preserve incoming edges across a file
1641	   * re-index (issue #899). Same edge-kind rules as
1642	   * {@link getDependentFilePaths}: all kinds except `contains`.
1643	   */
1644	  getCrossFileIncomingEdgesWithTarget(
1645	    filePath: string
1646	  ): Array<Edge & { targetName: string; targetKind: NodeKind; sourceFilePath: string; sourceLanguage: Language }> {
1647	    const sql = `SELECT e.*, tgt.name AS target_name, tgt.kind AS target_kind,
1648	        src.file_path AS source_file_path, src.language AS source_language
1649	      FROM edges e
1650	      JOIN nodes tgt ON tgt.id = e.target
1651	      JOIN nodes src ON src.id = e.source
1652	      WHERE tgt.file_path = ?
1653	        AND e.kind != 'contains'
1654	        AND src.file_path != ?`;
1655	    const rows = this.db.prepare(sql).all(filePath, filePath) as Array<
1656	      EdgeRow & { target_name: string; target_kind: NodeKind; source_file_path: string; source_language: Language }
1657	    >;
1658	    return rows.map(row => ({
1659	      ...rowToEdge(row),
1660	      targetName: row.target_name,
1661	      targetKind: row.target_kind,
1662	      sourceFilePath: row.source_file_path,
1663	      sourceLanguage: row.source_language,
1664	    }));
1665	  }
