1933	   */
1934	  getUnresolvedReferencesByFiles(filePaths: string[]): UnresolvedReference[] {
1935	    if (filePaths.length === 0) return [];
1936	
1937	    // Chunk under SQLite's parameter limit: the first sync of a very large repo
1938	    // passes every changed file here, which an unbounded `IN (...)` would bind
1939	    // as one parameter each — exceeding MAX_VARIABLE_NUMBER and aborting with
1940	    // "too many SQL variables". (#540)
1941	    const rows: UnresolvedRefRow[] = [];
1942	    for (let i = 0; i < filePaths.length; i += SQLITE_PARAM_CHUNK_SIZE) {
1943	      const chunk = filePaths.slice(i, i + SQLITE_PARAM_CHUNK_SIZE);
1944	      const placeholders = chunk.map(() => '?').join(',');
1945	      const chunkRows = this.db
1946	        .prepare(`SELECT * FROM unresolved_refs WHERE status = 'pending' AND file_path IN (${placeholders})`)
1947	        .all(...chunk) as UnresolvedRefRow[];
1948	      rows.push(...chunkRows);
1949	    }
1950	
1951	    return rows.map((row) => ({
1952	      fromNodeId: row.from_node_id,
1953	      referenceName: row.reference_name,
1954	      referenceKind: row.reference_kind as EdgeKind,
1955	      line: row.line,
1956	      column: row.col,
1957	      candidates: row.candidates ? safeJsonParse(row.candidates, undefined) : undefined,
