2010	   * caller's same-named call sites, the later sites' edges were silently never
2011	   * created (#1269).
2012	   */
2013	  deleteReferencesByRowIds(rowIds: number[]): void {
2014	    if (rowIds.length === 0) return;
2015	    for (let i = 0; i < rowIds.length; i += SQLITE_PARAM_CHUNK_SIZE) {
2016	      const chunk = rowIds.slice(i, i + SQLITE_PARAM_CHUNK_SIZE);
