2046	   * markReferencesFailed, for the same reason as deleteReferencesByRowIds:
2047	   * the key-tuple variant also flips same-key sibling rows in later batches
2048	   * to 'failed' before they were ever attempted (#1269). Resolution outcome
2049	   * can differ per call site (receiver-type inference reads the ref's line),
2050	   * so a sibling must not inherit this row's failure.
2051	   */
2052	  markReferencesFailedByRowIds(refs: Array<{ rowId: number; referenceName: string }>): void {
2053	    if (refs.length === 0) return;
2054	    const stmt = this.db.prepare(
2055	      "UPDATE unresolved_refs SET status = 'failed', name_tail = ? WHERE id = ?"
2056	    );
2057	    const markMany = this.db.transaction((items: typeof refs) => {
2058	      for (const ref of items) {
2059	        stmt.run(referenceNameTail(ref.referenceName), ref.rowId);
2060	      }
2061	    });
2062	    markMany(refs);
