2065	  /**
2066	   * Failed refs whose name tail matches one of the given symbol names — the
2067	   * candidates a sync should retry after files carrying those names changed
2068	   * (#1240). Names matching more than `perNameCeiling` failed refs are
2069	   * skipped entirely: at that population a name is external/builtin noise
2070	   * (`get`, `map`, …) that one new definition won't resolve — the same
2071	   * rationale as resolution's AMBIGUOUS_NAME_CEILING (#999) — and retrying an
2072	   * arbitrary subset would be both wasted work and incoherent coverage.
2073	   */
2074	  getRetryableFailedReferences(names: string[], perNameCeiling: number = 500): UnresolvedReference[] {
2075	    if (names.length === 0) return [];
2076	
2077	    // Pass 1: per-tail counts, chunked under the SQLite parameter limit.
2078	    const retryNames: string[] = [];
2079	    for (let i = 0; i < names.length; i += SQLITE_PARAM_CHUNK_SIZE) {
2080	      const chunk = names.slice(i, i + SQLITE_PARAM_CHUNK_SIZE);
2081	      const placeholders = chunk.map(() => '?').join(',');
