213	/**
214	 * Per-file pending entry — tracks a source file the watcher saw an event for
215	 * but hasn't yet synced into the index. Exposed via {@link FileWatcher.getPendingFiles}
216	 * so MCP tool responses can mark stale results without forcing a wait.
217	 */
218	export interface PendingFile {
219	  /** Project-relative POSIX path (e.g. "src/foo.ts"). */
220	  path: string;
221	  /** Wall-clock ms at the first event we saw for this path since the last sync. */
222	  firstSeenMs: number;
223	  /** Wall-clock ms at the most recent event we saw for this path. */
224	  lastSeenMs: number;
225	  /**
226	   * True when a sync is currently in flight that began AFTER this file's most
227	   * recent event — i.e. the next successful sync will pick it up. False when
228	   * the file is still in the debounce window (no sync running yet).
229	   */
230	  indexing: boolean;
231	}
232	
233	/**
234	 * FileWatcher monitors a project directory for changes and triggers
235	 * debounced sync operations via a provided callback.
236	 *
237	 * Design goals:
238	 * - Bounded resource usage: O(1) descriptors on macOS/Windows (one recursive
239	 *   watch), O(directories) inotify watches on Linux — never O(files), which
240	 *   was the system-crashing fd leak on macOS (#644/#496/#555/#628).
241	 * - Debounced to avoid thrashing on rapid saves
242	 * - Filters to supported source files by extension
243	 * - Ignores .codegraph/ and .git/ regardless of .gitignore
244	 * - Tracks per-file pending state so MCP tools can flag stale results
245	 *   without blocking on a sync (issue #403)
246	 */
247	export class FileWatcher {
248	  /** macOS/Windows: the single recursive watcher. Null on Linux. */
249	  private recursiveWatcher: fs.FSWatcher | null = null;
250	  /** Linux: one watcher per watched directory (keyed by absolute path). */
251	  private dirWatchers = new Map<string, fs.FSWatcher>();
252	  /** Set once the per-directory watch cap is hit, so we log only once. */
253	  private dirCapWarned = false;
254	  /**
255	   * Set once the Linux inotify watch limit (ENOSPC) is hit. Double duty: we
256	   * warn only once, AND we stop attempting new directory watches for the rest
257	   * of the session — once the kernel budget is exhausted every further
258	   * `inotify_add_watch` fails too, so trying the rest of the tree is pure
259	   * waste. NON-fatal (does not degrade): installed watches keep working.
260	   */
261	  private inotifyLimitWarned = false;
262	  /**
263	   * One-way latch: the reason live watching was permanently disabled at runtime
264	   * (watch-resource exhaustion, lock contention past the retry budget, or a
265	   * persistent generic sync failure past the retry budget), or null while
266	   * healthy. Set by {@link degrade}; cleared only by a fresh start().
267	   */
268	  private degradedReason: string | null = null;
269	  /** Consecutive lock-contention retries for watcher-triggered syncs. */
270	  private lockRetryCount = 0;
271	  /** Consecutive generic (non-lock) sync failures; reset only by a clean sync. */
272	  private syncFailureRetryCount = 0;
273	  /** Test-only inert mode: started, but with no OS watcher installed. */
274	  private inert = false;
275	  private debounceTimer: ReturnType<typeof setTimeout> | null = null;
276	  /**
277	   * Files seen by the watcher since the last successful sync — populated on
278	   * every change event, cleared at the start of a sync, and re-populated by
279	   * events that arrive mid-sync (or restored on sync failure). Keyed by the
280	   * same project-relative POSIX path the rest of the codebase uses, so a
281	   * caller can intersect tool-response file paths against this map cheaply.
282	   */
283	  private pendingFiles = new Map<string, { firstSeenMs: number; lastSeenMs: number }>();
284	  /**
285	   * Wall-clock ms at which the in-flight sync began. Combined with
286	   * {@link pendingFiles}'s `lastSeenMs`, this distinguishes "still in the
287	   * debounce window" (lastSeen > syncStarted, sync hasn't started yet for
288	   * this edit) from "currently being indexed" (lastSeen <= syncStarted).
289	   */
290	  private syncStartedMs = 0;
291	  private syncing = false;
292	  private stopped = false;
293	  /**
294	   * True once the initial watch set is established. Unlike the previous
295	   * chokidar implementation there is no asynchronous initial "crawl" emitting
296	   * an `add` per existing file — `fs.watch` only reports changes from the
297	   * moment it's installed — so this flips to true synchronously at the end of
298	   * `start()`. The startup reconcile against on-disk state is handled
299	   * separately by the engine's catch-up sync, not by the watcher.
300	   */
301	  private ready = false;
302	  /**
303	   * Callbacks that resolve when the watch set is established. Used by tests
304	   * (and any production caller that cares about a clean baseline) to
305	   * deterministically gate on watcher readiness.
306	   */
307	  private readyWaiters: Array<() => void> = [];
308	  // The shared scope matcher (built-in defaults + project .gitignore, with
309	  // embedded child repos matched by their OWN rules — #514), built once at
310	  // start(). Same source of truth the indexer uses, so watcher scope can
311	  // never diverge from index scope. An embedded repo created after start()
312	  // joins the scope on the next watcher restart / re-index.
313	  private ignoreMatcher: ScopeIgnore | null = null;
314	
315	  private readonly projectRoot: string;
316	  private readonly debounceMs: number;
317	  private readonly syncFn: () => Promise<{ filesChanged: number; durationMs: number }>;
318	  private readonly onSyncComplete?: WatchOptions['onSyncComplete'];
319	  private readonly onSyncError?: WatchOptions['onSyncError'];
320	  private readonly onDegraded?: WatchOptions['onDegraded'];
321	  private readonly inertForTests: boolean;
322	
323	  constructor(
324	    projectRoot: string,
325	    syncFn: () => Promise<{ filesChanged: number; durationMs: number }>,
326	    options: WatchOptions = {}
327	  ) {
328	    this.projectRoot = projectRoot;
329	    this.syncFn = syncFn;
330	    this.debounceMs = options.debounceMs ?? 2000;
331	    this.onSyncComplete = options.onSyncComplete;
332	    this.onSyncError = options.onSyncError;
333	    this.onDegraded = options.onDegraded;
334	    this.inertForTests = options.inertForTests ?? false;
335	  }
336	
337	  /**
338	   * Start watching for file changes.
339	   * Returns true if watching started successfully, false otherwise.
340	   */
341	  start(): boolean {
342	    if (this.recursiveWatcher || this.dirWatchers.size > 0 || this.inert) return true; // Already watching
343	    this.stopped = false;
344	    this.degradedReason = null;
345	    this.lockRetryCount = 0;
346	    this.syncFailureRetryCount = 0;
347	
348	    // Some environments make filesystem watching unusable — most notably
349	    // WSL2 /mnt/ drives, where the underlying fs.watch calls block long
350	    // enough to break MCP startup handshakes (issue #199). Skip watching
351	    // there; callers fall back to manual `codegraph sync` or git sync hooks.
352	    const disabledReason = watchDisabledReason(this.projectRoot);
353	    if (disabledReason) {
354	      logDebug('File watcher disabled', { reason: disabledReason, projectRoot: this.projectRoot });
355	      return false;
356	    }
357	
358	    // Reuse the indexer's ignore set so the watcher and indexer agree on scope.
359	    this.ignoreMatcher = buildScopeIgnore(this.projectRoot);
360	
361	    try {
362	      if (this.inertForTests) {
363	        // Test-only: install no OS watcher; the seam drives events instead.
364	        this.inert = true;
365	      } else if (supportsRecursiveWatch()) {
366	        this.startRecursive();
367	      } else {
368	        this.startPerDirectory();
369	      }
370	
371	      // The per-directory (Linux) path catches watch-resource exhaustion inside
372	      // watchTree and degrades synchronously rather than throwing, so it never
373	      // reaches the catch below. Surface that as a failed start here so both
374	      // strategies report exhaustion identically (start() === false).
375	      if (this.degradedReason) return false;
376	
377	      // No async crawl to wait on: as soon as the watch set is installed we
378	      // have a clean baseline (pendingFiles is only populated by post-start
379	      // events). Clear defensively and flip ready.
380	      this.pendingFiles.clear();
381	      this.ready = true;
382	      for (const cb of this.readyWaiters) cb();
383	      this.readyWaiters.length = 0;
384	      if (IS_TEST_RUNTIME) liveWatchersForTests.set(this.projectRoot, this);
385	
386	      logDebug('File watcher started', {
387	        projectRoot: this.projectRoot,
388	        debounceMs: this.debounceMs,
389	        mode: this.inertForTests ? 'inert' : supportsRecursiveWatch() ? 'recursive' : 'per-directory',
390	        watchedDirs: this.dirWatchers.size || undefined,
391	      });
392	      return true;
393	    } catch (err) {
394	      // Watcher setup failed. Watch-resource exhaustion (EMFILE/ENFILE on the
395	      // recursive path) is terminal — degrade cleanly with one actionable
396	      // warning instead of leaving a half-broken watcher. Everything else
397	      // (permission denied, missing directory) keeps the prior quiet-stop.
398	      if (isWatchResourceExhaustion(err)) {
399	        this.degrade(EXHAUSTION_REASON, { error: String(err) });
400	      } else {
401	        logWarn('Could not start file watcher', { error: String(err) });
402	        this.stop();
403	      }
404	      return false;
405	    }
406	  }
407	
408	  /**
409	   * macOS/Windows: one recursive watcher for the whole tree. O(1) descriptors.
410	   * `filename` arrives relative to the project root (with subdirectories), so
411	   * it maps straight to a project-relative path.
412	   */
413	  private startRecursive(): void {
414	    this.recursiveWatcher = watchImpl(
415	      this.projectRoot,
416	      { recursive: true, persistent: true },
417	      (_event, filename) => {
418	        if (this.stopped || filename == null) return;
419	        this.handleChange(normalizePath(String(filename)));
420	      }
421	    );
422	    this.recursiveWatcher.on('error', (err: unknown) => {
423	      if (isWatchResourceExhaustion(err)) {
424	        this.degrade(EXHAUSTION_REASON, { error: String(err) });
425	        return;
426	      }
427	      logWarn('File watcher error', { error: String(err) });
428	    });
429	  }
430	
431	  /**
432	   * Linux: walk the (non-ignored) tree and watch each directory. One inotify
433	   * watch per directory reports create/modify/delete for that directory's
434	   * direct children, so we never watch individual files.
435	   */
436	  private startPerDirectory(): void {
437	    this.watchTree(this.projectRoot, /* markExisting */ false);
438	  }
439	
440	  /**
441	   * Add an inotify watch for `dir` and recurse into its non-ignored
442	   * subdirectories. When `markExisting` is true (a directory that appeared
443	   * AFTER startup), the source files already inside it are recorded as pending
444	   * — this closes the `mkdir + write` race where files created before the new
445	   * directory's watch is installed would otherwise be missed until the next
446	   * full sync. The initial startup walk passes false (the engine's catch-up
447	   * sync owns the baseline).
448	   */
449	  private watchTree(dir: string, markExisting: boolean): void {
450	    // A degrade() mid-walk (exhaustion on an earlier directory) calls stop(),
451	    // which sets `stopped`; bail so the recursion unwinds without adding more
452	    // watches to a watcher that is shutting down. `inotifyLimitWarned` does the
453	    // same after ENOSPC — the kernel budget is gone, so stop trying the rest of
454	    // the tree (every add would fail) while keeping the watches already set.
455	    if (this.stopped || this.degradedReason || this.inotifyLimitWarned) return;
456	    if (this.dirWatchers.has(dir)) return;
457	    if (this.dirWatchers.size >= maxDirWatches()) {
458	      if (!this.dirCapWarned) {
459	        this.dirCapWarned = true;
460	        logWarn('File watcher hit directory-watch cap; remaining subtrees rely on manual/periodic sync', {
461	          cap: maxDirWatches(),
462	        });
463	      }
464	      return;
465	    }
466	
467	    let w: fs.FSWatcher;
468	    try {
469	      w = watchImpl(dir, { persistent: true }, (_event, filename) =>
470	        this.handleDirEvent(dir, filename)
471	      );
472	    } catch (err) {
473	      // EMFILE/ENFILE means the PROCESS is out of descriptors — every further
474	      // directory would fail too, so degrade the whole watcher rather than
475	      // limping along with a partial watch set.
476	      if (isWatchResourceExhaustion(err)) {
477	        this.degrade(EXHAUSTION_REASON, { error: String(err), dir });
478	      } else if (isInotifyWatchExhaustion(err)) {
479	        // ENOSPC = inotify watch budget exhausted. NON-fatal: keep the watches
480	        // we have and tell the user the knob to raise (warn once).
481	        this.warnInotifyLimit({ error: String(err), dir });
482	      }
483	      // ENOENT / EACCES on a single directory stays non-fatal: skip it quietly.
484	      return;
485	    }
486	    w.on('error', (err: unknown) => {
487	      if (isWatchResourceExhaustion(err)) {
488	        this.degrade(EXHAUSTION_REASON, { error: String(err), dir });
489	        return;
490	      }
491	      if (isInotifyWatchExhaustion(err)) {
492	        this.warnInotifyLimit({ error: String(err), dir });
493	      }
494	      this.unwatchDir(dir);
495	    });
496	    this.dirWatchers.set(dir, w);
497	
498	    let entries: fs.Dirent[];
499	    try {
500	      entries = fs.readdirSync(dir, { withFileTypes: true });
501	    } catch {
502	      return;
503	    }
504	    for (const entry of entries) {
505	      const child = path.join(dir, entry.name);
506	      if (entry.isDirectory()) {
507	        if (this.shouldIgnoreDir(child)) continue;
508	        this.watchTree(child, markExisting);
509	      } else if (markExisting && entry.isFile()) {
510	        this.handleChange(normalizePath(path.relative(this.projectRoot, child)));
511	      }
512	    }
513	  }
514	
515	  /**
516	   * Linux per-directory event handler. `filename` is relative to `dir`. A new
517	   * sub-directory is picked up by extending the watch tree; everything else is
518	   * routed through the shared change handler.
519	   */
520	  private handleDirEvent(dir: string, filename: string | Buffer | null): void {
521	    if (this.stopped || filename == null) return;
522	    const full = path.join(dir, String(filename));
523	
524	    // A newly-created directory needs its own watch (recursive isn't available
525	    // on Linux). statSync is cheap and these events are rare relative to file
526	    // edits. If the path vanished (rapid create/delete) the stat throws and we
527	    // fall through to the change handler, which no-ops on a non-source path.
528	    try {
529	      if (fs.statSync(full).isDirectory()) {
530	        if (!this.shouldIgnoreDir(full)) this.watchTree(full, /* markExisting */ true);
531	        return;
532	      }
533	    } catch {
534	      // deleted/inaccessible — treat as a normal change below
535	    }
536	
537	    this.handleChange(normalizePath(path.relative(this.projectRoot, full)));
538	  }
539	
540	  /**
541	   * Shared change handler for both watch strategies. `rel` is a
542	   * project-relative POSIX path. Applies the ignore + source-file filters and,
543	   * for a real source change, records it as pending (#403) and schedules a
544	   * debounced sync.
545	   *
546	   * The recursive (macOS/Windows) watcher reports events for ignored trees too
547	   * (one stream covers the whole repo), so the ignore check here is load-bearing
548	   * — it drops node_modules/dist/.git churn before any sync is scheduled.
549	   */
550	  private handleChange(rel: string): void {
551	    if (!rel || rel === '.' || rel.startsWith('..')) return;
552	    if (this.isAlwaysIgnored(rel)) return;
553	    if (this.ignoreMatcher && this.ignoreMatcher.ignores(rel)) return;
554	    if (!isSourceFile(rel, loadExtensionOverrides(this.projectRoot))) return;
555	
556	    logDebug('File change detected', { file: rel });
557	    if (this.ready) {
558	      const now = Date.now();
559	      const existing = this.pendingFiles.get(rel);
560	      this.pendingFiles.set(rel, {
561	        firstSeenMs: existing?.firstSeenMs ?? now,
562	        lastSeenMs: now,
563	      });
564	    }
565	    this.scheduleSync();
566	  }
567	
568	  /** Close and forget the watch for a directory that errored/was removed. */
569	  private unwatchDir(dir: string): void {
570	    const w = this.dirWatchers.get(dir);
571	    if (w) {
572	      try {
573	        w.close();
574	      } catch {
575	        /* already closed */
576	      }
577	      this.dirWatchers.delete(dir);
578	    }
579	  }
580	
581	  /** Our own dirs are always ignored, regardless of .gitignore. */
582	  private isAlwaysIgnored(rel: string): boolean {
583	    // First path segment. Ignore any CodeGraph data dir — the active one AND a
584	    // sibling like `.codegraph-win` a second environment (Windows/WSL) created
585	    // in the same tree, so neither side watches the other's index (#636).
586	    const top = rel.split('/')[0] ?? rel;
587	    return (
588	      isCodeGraphDataDir(top) ||
589	      rel === '.git' || rel.startsWith('.git/')
590	    );
591	  }
592	
593	  /**
594	   * True for any directory that should NOT be watched (used while building the
595	   * Linux per-directory watch tree). Tests the directory form of the path so a
596	   * dir-only ignore rule like `build/` matches.
597	   */
598	  private shouldIgnoreDir(dirPath: string): boolean {
599	    const rel = normalizePath(path.relative(this.projectRoot, dirPath));
600	    if (!rel || rel === '.' || rel.startsWith('..')) return false; // root / outside
601	    if (this.isAlwaysIgnored(rel)) return true;
602	    if (!this.ignoreMatcher) return false;
603	    return this.ignoreMatcher.ignores(rel + '/');
604	  }
605	
606	  /**
607	   * Permanently disable live watching after a terminal runtime failure
608	   * (watch-resource exhaustion, lock contention past the retry budget, or a
609	   * persistent generic sync failure past the retry budget).
610	   * Idempotent: logs one actionable warning, fires {@link WatchOptions.onDegraded}
611	   * once, and stops the watcher. A subsequent start() clears the latch.
612	   */
613	  private degrade(reason: string, context: Record<string, unknown> = {}): void {
614	    if (this.degradedReason) return;
615	    this.degradedReason = reason;
616	    logWarn('File watcher disabled', { projectRoot: this.projectRoot, reason, ...context });
617	    this.onDegraded?.(reason);
618	    this.stop();
619	  }
620	
621	  /**
622	   * Warn ONCE that the Linux inotify watch budget is exhausted (ENOSPC), and
623	   * stop adding new watches for the rest of this session — every further
624	   * `inotify_add_watch` would fail too, so walking the rest of the tree is
625	   * waste. Unlike {@link degrade} this is NON-fatal: the watches already
626	   * installed keep firing, and `codegraph sync` covers the unwatched remainder.
627	   * The message names the kernel knob to raise (`fs.inotify.max_user_watches`).
628	   */
629	  private warnInotifyLimit(context: Record<string, unknown> = {}): void {
630	    if (this.inotifyLimitWarned) return;
631	    this.inotifyLimitWarned = true;
632	    logWarn(INOTIFY_LIMIT_REASON, { watchedDirs: this.dirWatchers.size, ...context });
633	  }
634	
635	  /**
636	   * Whether live watching has degraded permanently (until the next start()).
637	   * Distinct from {@link isActive}: a degraded watcher is inactive, but an
638	   * inactive watcher is not necessarily degraded (it may simply be stopped or
639	   * never started). Hosts use this to tell the user auto-sync is off.
640	   */
641	  isDegraded(): boolean {
642	    return this.degradedReason !== null;
643	  }
644	
645	  /** The reason live watching degraded, or null if it is healthy. */
646	  getDegradedReason(): string | null {
647	    return this.degradedReason;
648	  }
649	
650	  /**
651	   * Stop watching for file changes.
652	   */
653	  stop(): void {
654	    this.stopped = true;
655	
656	    if (this.debounceTimer) {
657	      clearTimeout(this.debounceTimer);
658	      this.debounceTimer = null;
659	    }
660	
661	    if (this.recursiveWatcher) {
662	      try {
663	        this.recursiveWatcher.close();
664	      } catch {
665	        /* already closed */
666	      }
667	      this.recursiveWatcher = null;
668	    }
669	    for (const w of this.dirWatchers.values()) {
670	      try {
671	        w.close();
672	      } catch {
673	        /* already closed */
674	      }
675	    }
676	    this.dirWatchers.clear();
677	    this.dirCapWarned = false;
678	    this.inotifyLimitWarned = false;
679	    this.lockRetryCount = 0;
680	    this.syncFailureRetryCount = 0;
681	    // NB: degradedReason is intentionally NOT reset here — it must survive the
682	    // stop() that degrade() triggers so isDegraded() stays true. start() clears it.
683	    this.inert = false;
684	
685	    this.pendingFiles.clear();
686	    this.ready = false;
687	    this.ignoreMatcher = null;
688	    if (IS_TEST_RUNTIME) liveWatchersForTests.delete(this.projectRoot);
689	    logDebug('File watcher stopped');
690	  }
691	
692	  /**
693	   * @internal Test-only: feed a synthetic project-relative change through the
694	   * same filter → pendingFiles → debounced-sync path a real fs.watch event
695	   * takes. Lets the watcher / staleness-banner suites stay deterministic
696	   * instead of racing on OS watch-delivery latency. See
697	   * {@link __emitWatchEventForTests}.
698	   */
699	  ingestEventForTests(relPath: string): void {
700	    this.handleChange(normalizePath(relPath));
701	  }
702	
703	  /**
704	   * Whether the watcher is currently active.
705	   */
706	  isActive(): boolean {
707	    return (this.recursiveWatcher !== null || this.dirWatchers.size > 0 || this.inert) && !this.stopped;
708	  }
709	
710	  /**
711	   * Resolves once the watch set has been installed (or immediately if it
712	   * already has). Useful for tests that need a deterministic boundary before
713	   * asserting on `pendingFiles`.
714	   *
715	   * Production callers don't need this: `pendingFiles` is read continuously,
716	   * the staleness banner is always correct (empty or populated), and there is
717	   * no asynchronous initial-scan window with `fs.watch`.
718	   */
719	  waitUntilReady(timeoutMs = 10000): Promise<void> {
720	    if (this.ready) return Promise.resolve();
721	    return new Promise((resolve, reject) => {
722	      const t = setTimeout(() => {
723	        const idx = this.readyWaiters.indexOf(handler);
724	        if (idx >= 0) this.readyWaiters.splice(idx, 1);
725	        reject(new Error(`FileWatcher.waitUntilReady timed out after ${timeoutMs}ms`));
726	      }, timeoutMs);
727	      const handler = () => { clearTimeout(t); resolve(); };
728	      this.readyWaiters.push(handler);
729	    });
730	  }
731	
732	  /**
733	   * Schedule a normal debounced sync after a source edit.
734	   */
735	  private scheduleSync(): void {
736	    if (this.debounceTimer) {
737	      clearTimeout(this.debounceTimer);
738	    }
739	    this.debounceTimer = setTimeout(() => {
740	      this.debounceTimer = null;
741	      this.flush();
742	    }, this.debounceMs);
743	  }
744	
745	  /**
746	   * Schedule a retry after a recoverable sync failure (lock contention). Kept
747	   * separate from {@link scheduleSync} so prolonged contention backs off
748	   * exponentially instead of hammering the lock every debounce cycle.
749	   */
750	  private scheduleRetrySync(delayMs: number): void {
751	    if (this.debounceTimer) {
752	      clearTimeout(this.debounceTimer);
753	    }
754	    this.debounceTimer = setTimeout(() => {
755	      this.debounceTimer = null;
756	      this.flush();
757	    }, delayMs);
758	  }
759	
760	  /**
761	   * Flush pending changes by running sync.
762	   *
763	   * pendingFiles is NOT cleared at the start of sync — entries are removed
764	   * only after sync commits successfully, and only for entries whose
765	   * lastSeenMs <= syncStartedMs. That way, a query that arrives mid-sync
766	   * still sees the affected files marked stale (the DB hasn't been updated
767	   * yet), and an event that lands mid-sync persists into the follow-up.
768	   *
769	   * On sync failure pendingFiles is left untouched — every edit is still
770	   * unindexed, and the rescheduled sync will absorb the same set next time.
771	   */
772	  private async flush(): Promise<void> {
773	    // If already syncing, the post-sync check will re-trigger
774	    if (this.syncing || this.stopped) return;
775	
776	    this.syncStartedMs = Date.now();
777	    this.syncing = true;
778	
