468	        try { this.queries.setMetadata('index_state', 'indexing'); } catch { /* metadata is advisory */ }
469	        // Segment vocabulary starts empty and is repopulated by the node write
470	        // path as every file (re-)indexes below — so a full index is also the
471	        // orphan-cleanup pass for names deleted since the last one.
472	        try { this.queries.clearNameSegmentVocab(); } catch { /* vocab is advisory — never fail an index over it */ }
473	        const result = await this.orchestrator.indexAll(
474	          options.onProgress,
475	          options.signal,
476	          options.verbose,
477	          walValve ? () => walValve!.backpressure() : undefined
478	        );
479	
480	        // Fold the parse phase's WAL BEFORE the first post-parse reads
481	        // (resolver re-init and resolution both read on the main thread):
482	        // paging a bulk-write-sized WAL there is what blew the #850
483	        // watchdog's 60s window in the #1231 repro. Off-thread + awaited,
484	        // so the event loop keeps turning.
485	        if (walValve) await walValve.foldNow();
486	
487	        // Re-detect frameworks now that the index is populated. The resolver
488	        // is constructed with createResolver() before any files exist, so
489	        // framework resolvers whose detect() consults the indexed file list
490	        // (e.g. UIKit/SwiftUI scanning for imports, swift-objc-bridge looking
491	        // for both Swift and ObjC files) all return false on that initial pass
492	        // and silently drop themselves. Re-initializing here gives them a
493	        // chance to see the actual project before resolution runs.
494	        if (result.success && result.filesIndexed > 0) {
495	          this.resolver.initialize();
496	          // Cross-file finalization (e.g. NestJS RouterModule prefixes). Runs
497	          // before resolution so updated names show up in subsequent reads.
498	          this.resolver.runPostExtract();
499	        }
500	
501	        // Resolve references to create call/import/extends edges
502	        if (result.success && result.filesIndexed > 0) {
503	          // Get count without loading all refs into memory
504	          const unresolvedCount = this.queries.getUnresolvedReferencesCount();
505	
506	          options.onProgress?.({
507	            phase: 'resolving',
508	            current: 0,
509	            total: unresolvedCount,
510	          });
511	
512	          await this.resolveReferencesBatched((current, total) => {
513	            options.onProgress?.({
514	              phase: 'resolving',
515	              current,
516	              total,
517	            });
518	          });
519	
520	          // Second pass: chained calls whose method lives on a supertype the
521	          // receiver conforms to (protocol-extension / inherited / default-
522	          // interface). Needs the implements/extends edges the main pass just
523	          // built, so it runs after resolution (#750).
524	          const tChained = Date.now();
525	          await this.resolver.resolveChainedCallsViaConformance();
526	          if (process.env.CODEGRAPH_SYNTH_TIMINGS) console.error(`[synth-timing] chainedConformance: ${Date.now() - tChained}ms`);
527	          // Same lifecycle for `this.<member>` callback registrations whose
528	          // member is inherited from a supertype (#808).
529	          const tDeferred = Date.now();
530	          await this.resolver.resolveDeferredThisMemberRefs();
531	          if (process.env.CODEGRAPH_SYNTH_TIMINGS) console.error(`[synth-timing] deferredThisMember: ${Date.now() - tDeferred}ms`);
532	        }
533	
534	        // Refresh planner stats + checkpoint the WAL after bulk writes.
535	        // Off-thread (worker connection): on a multi-GB index this is minutes
536	        // of IO, and inline it starved the #850 watchdog AFTER a fully
537	        // successful index. Never load-bearing for correctness.
538	        if (result.success && result.filesIndexed > 0) {
539	          const tMaint = Date.now();
540	          // Quiesce the valve first so its in-flight checkpoint and the
541	          // maintenance checkpoint don't contend for the checkpointer lock
542	          // (the loser would silently no-op and leave the WAL unfolded).
543	          if (walValve) { walValve.stop(); await walValve.drain(); }
544	          await this.db.runMaintenance();
545	          if (process.env.CODEGRAPH_SYNTH_TIMINGS) console.error(`[phase-timing] maintenance: ${Date.now() - tMaint}ms`);
546	        }
547	
548	        // The orchestrator only sees extraction-phase counts; resolution and
549	        // synthesizer edges (often >50% of the graph on JVM repos) come later.
550	        // Recompute against the DB so the CLI summary reports the true totals.
551	        if (result.success && result.filesIndexed > 0) {
552	          const tCount = Date.now();
553	          const after = this.queries.getNodeAndEdgeCount();
554	          if (process.env.CODEGRAPH_SYNTH_TIMINGS) console.error(`[phase-timing] count-recompute: ${Date.now() - tCount}ms`);
555	          result.nodesCreated = after.nodes - before.nodes;
556	          result.edgesCreated = after.edges - before.edges;
557	        }
558	
559	        // Stamp the index with the engine that built it, so `codegraph status`
560	        // and `codegraph upgrade` can recommend a re-index when the running
561	        // engine produces richer extraction than the one on disk. Only on a
562	        // real full index — a sync touches a subset, so it must NOT advance the
563	        // extraction stamp (the bulk would still be stale). See extraction-version.ts.
564	        if (result.success && result.filesIndexed > 0) {
565	          try {
566	            this.queries.setMetadata('indexed_with_version', CodeGraphPackageVersion);
567	            this.queries.setMetadata('indexed_with_extraction_version', String(EXTRACTION_VERSION));
568	          } catch { /* metadata is advisory — never fail an index over it */ }
569	        }
570	
571	        // Reconcile the scan's ground truth against what the pipeline
572	        // accounted for. A shortfall means files were silently dropped
573	        // (observed in the wild: a run under heavy load came up 37 files
574	        // short with no error) — record it and tell the user, don't let the
575	        // index pass as complete.
576	        try {
577	          if (!result.success) {
578	            this.queries.setMetadata('index_state', 'failed');
579	          } else {
580	            const accounted = result.filesIndexed + result.filesSkipped + result.filesErrored;
581	            const discovered = result.filesDiscovered;
582	            const shortfall = discovered !== undefined ? discovered - accounted : 0;
583	            if (discovered !== undefined && shortfall > 0) {
584	              this.queries.setMetadata('index_state', 'partial');
585	              this.queries.setMetadata('index_files_discovered', String(discovered));
586	              this.queries.setMetadata('index_files_accounted', String(accounted));
587	              result.errors.push({
588	                message: `Index is missing ${shortfall} of ${discovered} discovered files (indexed ${result.filesIndexed}, skipped ${result.filesSkipped}, errored ${result.filesErrored}). The index is PARTIAL — re-run \`codegraph index\`.`,
589	                severity: 'warning',
590	                code: 'index_partial',
591	              });
592	            } else {
593	              this.queries.setMetadata('index_state', 'complete');
594	              if (discovered !== undefined) {
595	                this.queries.setMetadata('index_files_discovered', String(discovered));
596	                this.queries.setMetadata('index_files_accounted', String(accounted));
597	              }
598	            }
599	          }
600	        } catch { /* metadata is advisory — never fail an index over it */ }
601	
602	        return result;
603	      } finally {
604	        // Restore the auto-checkpoint interval AFTER the fold-up above so the
605	        // next ordinary write doesn't inherit a giant inline checkpoint. On
606	        // the error path the WAL may still be large; correctness is unchanged
607	        // (SQLite replays the WAL on the next open) and the follow-up write
608	        // that folds it is the known cost of a failed run.
609	        if (walValve) { walValve.stop(); await walValve.drain(); }
610	        if (deferWal) {
611	          try { this.db.setWalAutocheckpoint(priorAutocheckpoint); } catch { /* connection may be closing */ }
612	        }
613	        this.fileLock.release();
614	      }
615	    });
616	  }
