618	  /**
619	   * Index specific files
620	   *
621	   * Uses a mutex to prevent concurrent indexing operations.
622	   */
623	  async indexFiles(filePaths: string[]): Promise<IndexResult> {
624	    return this.indexMutex.withLock(async () => {
625	      try {
626	        this.fileLock.acquire();
627	      } catch {
628	        return { success: false, filesIndexed: 0, filesSkipped: 0, filesErrored: 0, nodesCreated: 0, edgesCreated: 0, errors: [{ message: 'Could not acquire file lock - another process may be indexing', severity: 'error' as const }], durationMs: 0 };
629	      }
630	      try {
631	        return this.orchestrator.indexFiles(filePaths);
632	      } finally {
633	        this.fileLock.release();
634	      }
635	    });
636	  }
637	
638	  /**
639	   * Sync with current file state (incremental update)
640	   *
641	   * Uses a mutex to prevent concurrent indexing operations.
642	   */
643	  async sync(options: IndexOptions = {}): Promise<SyncResult> {
644	    return this.indexMutex.withLock(async () => {
645	      try {
646	        this.fileLock.acquire();
647	      } catch {
648	        return { filesChecked: 0, filesAdded: 0, filesModified: 0, filesRemoved: 0, nodesUpdated: 0, durationMs: 0 };
649	      }
650	      try {
651	        // Captured BEFORE the sync runs: the sync's own incremental writes
652	        // populate vocab rows for the files it touches, so an end-of-sync
653	        // emptiness check would see "non-empty" and skip the backfill forever,
654	        // leaving every unchanged file's names unsegmented.
655	        const vocabWasEmpty = (() => {
656	          try { return this.queries.isNameSegmentVocabEmpty(); } catch { return false; }
657	        })();
658	
659	        const result = await this.orchestrator.sync(options.onProgress);
660	
661	        // Cross-file finalization (e.g. NestJS RouterModule prefixes). Run on
662	        // every sync that touched files so edits to `app.module.ts` propagate
663	        // to controllers in unchanged files. The pass is idempotent and cheap
664	        // (regex over *.module.ts only).
665	        if (result.filesAdded > 0 || result.filesModified > 0) {
666	          this.resolver.runPostExtract();
667	        } else if (result.filesRemoved > 0) {
668	          // A pure-removal sync still resolves refs below — the deletion path
669	          // resurrects the removed file's incoming edges as pending refs
670	          // (#1240 removal case) and the orphan sweep consumes them. In a
671	          // long-lived process (daemon) the resolver's name caches were
672	          // warmed against the pre-removal graph; drop them so resolution
673	          // sees the post-removal state. (runPostExtract above clears caches
674	          // itself, so the changed-files branch is already covered.)
675	          this.resolver.clearCaches();
676	        }
677	
678	        // Resolve references if files were updated
679	        const filesChanged = result.filesAdded > 0 || result.filesModified > 0;
680	        if (filesChanged) {
681	          if (result.changedFilePaths) {
682	            // Scope resolution to changed files (git fast path — bounded set)
683	            const tRefLoad = Date.now();
684	            const unresolvedRefs = this.queries.getUnresolvedReferencesByFiles(result.changedFilePaths);
685	            if (process.env.CODEGRAPH_SYNTH_TIMINGS) console.error(`[phase-timing] sync-ref-load: ${Date.now() - tRefLoad}ms (${unresolvedRefs.length} refs)`);
686	
687	            options.onProgress?.({
688	              phase: 'resolving',
689	              current: 0,
690	              total: unresolvedRefs.length,
691	            });
692	
693	            this.resolver.resolveAndPersist(unresolvedRefs, (current, total) => {
694	              options.onProgress?.({
695	                phase: 'resolving',
696	                current,
697	                total,
698	              });
699	            });
700	
701	            // Retry previously-failed refs the changed files may now satisfy
702	            // (#1240). Scoped resolution above only re-resolves refs FROM the
703	            // changed files — but when a changed file gains an export/symbol,
704	            // refs in UNCHANGED files that failed against the old graph can
705	            // now resolve, and nothing else ever revisits them (their rows
706	            // were parked as status='failed' by an earlier completed pass).
707	            // Look them up by the symbol names the changed files now carry
708	            // and re-resolve just that set. On a sync where no failed ref
709	            // matches, this is one indexed lookup.
710	            const tRetry = Date.now();
711	            const retryable = this.queries.getRetryableFailedReferences(
712	              this.queries.getNodeNamesByFiles(result.changedFilePaths)
713	            );
714	            if (retryable.length > 0) {
715	              options.onProgress?.({
716	                phase: 'resolving',
717	                current: 0,
718	                total: retryable.length,
719	              });
720	              await this.resolver.resolveAndPersistListYielding(retryable);
721	              options.onProgress?.({
722	                phase: 'resolving',
723	                current: retryable.length,
724	                total: retryable.length,
725	              });
726	            }
727	            if (process.env.CODEGRAPH_SYNTH_TIMINGS) console.error(`[phase-timing] sync-failed-ref-retry: ${Date.now() - tRetry}ms (${retryable.length} refs)`);
728	          } else {
729	            // No git info — use batched resolution to avoid OOM
730	            const unresolvedCount = this.queries.getUnresolvedReferencesCount();
731	
732	            options.onProgress?.({
733	              phase: 'resolving',
734	              current: 0,
735	              total: unresolvedCount,
736	            });
737	
738	            await this.resolveReferencesBatched((current, total) => {
739	              options.onProgress?.({
740	                phase: 'resolving',
741	                current,
742	                total,
743	              });
744	            });
745	          }
746	        }
747	
748	        // Orphan sweep (#1187). A resolution pass that dies mid-run — the #850
749	        // daemon liveness watchdog's SIGKILL (#1122), Ctrl-C, a crash — leaves
750	        // the refs it never reached in unresolved_refs, and the git-scoped fast
751	        // path above never revisits them (it reads only the changed files'
752	        // rows). Those files' call edges were then missing PERMANENTLY, with
753	        // nothing to see except a too-small blast radius, until a full
754	        // re-index. A completed pass takes every row it processed out of the
755	        // PENDING set (resolved rows are deleted, unresolvable ones parked as
756	        // status='failed' for the #1240 retry above), so any pending row now
757	        // is such an orphan — or a row from an older engine's scoped pass.
758	        // Grind them down with the batched resolver; this also makes a bare
759	        // `codegraph sync` the recovery command for a wedged index. On a
760	        // healthy index this is one COUNT query.
761	        const orphanCount = this.queries.getUnresolvedReferencesCount();
762	        if (orphanCount > 0) {
763	          options.onProgress?.({
764	            phase: 'resolving',
765	            current: 0,
766	            total: orphanCount,
767	          });
768	
769	          await this.resolveReferencesBatched((current, total) => {
770	            options.onProgress?.({
771	              phase: 'resolving',
772	              current,
773	              total,
774	            });
775	          });
776	        }
777	
778	        if (filesChanged || orphanCount > 0) {
779	          // Second pass: chained calls whose method lives on a supertype the
780	          // receiver conforms to (protocol-extension / inherited). Needs the
781	          // implements/extends edges built above (#750).
782	          await this.resolver.resolveChainedCallsViaConformance();
783	          // Same lifecycle for `this.<member>` callback registrations whose
784	          // member is inherited from a supertype (#808).
785	          await this.resolver.resolveDeferredThisMemberRefs();
786	        }
787	
788	        // Refresh planner stats + checkpoint the WAL after bulk writes.
789	        // Off-thread — see indexAll's call site.
790	        if (filesChanged || result.filesRemoved > 0 || orphanCount > 0) {
791	          await this.db.runMaintenance();
792	        }
793	
794	        // Heal the segment vocabulary on indexes built before the table
795	        // existed (upgrade path): incremental writes above only cover changed
796	        // files, so a vocab that was empty when this sync STARTED means the
797	        // bulk was never segmented — backfill it (INSERT OR IGNORE, so the
798	        // rows the sync just wrote are fine). Batched + yielding — sync can
799	        // run on the daemon's liveness-watchdog thread (#850/#1091).
800	        try {
801	          if (vocabWasEmpty && this.queries.getNodeAndEdgeCount().nodes > 0) {
802	            await this.rebuildNameSegmentVocab();
803	          }
804	        } catch { /* vocab is advisory — never fail a sync over it */ }
805	
806	        return result;
807	      } finally {
808	        this.fileLock.release();
809	      }
810	    });
811	  }
