824	  /**
825	   * Start watching for file changes and auto-syncing.
826	   *
827	   * Uses native OS file events (FSEvents on macOS, inotify on Linux 19+,
828	   * ReadDirectoryChangesW on Windows) with debouncing to avoid thrashing.
829	   *
830	   * @param options - Watch options (debounce delay, callbacks)
831	   * @returns true if watching started successfully
832	   */
833	  watch(options: WatchOptions = {}): boolean {
834	    if (this.watcher?.isActive()) return true;
835	
836	    this.watcher = new FileWatcher(
837	      this.projectRoot,
838	      async () => {
839	        const result = await this.sync();
840	        // sync() returns this exact zero-shape iff it failed to acquire the
841	        // file lock (a real empty sync always has filesChecked > 0 because
842	        // scanDirectory ran). Surface that to the watcher as a typed error
843	        // so it keeps pendingFiles + reschedules instead of clearing them
844	        // (#449).
845	        if (result.filesChecked === 0 && result.durationMs === 0) {
846	          throw new LockUnavailableError();
847	        }
848	        const filesChanged = result.filesAdded + result.filesModified + result.filesRemoved;
849	        return { filesChanged, durationMs: result.durationMs };
850	      },
851	      options
852	    );
853	
854	    return this.watcher.start();
855	  }
