923	  /**
924	   * Most recent index timestamp (ms since epoch) across all tracked files, or
925	   * null when nothing is indexed yet. Lets library consumers check index
926	   * freshness without shelling out to `codegraph status --json`. (#329)
927	   */
928	  getLastIndexedAt(): number | null {
929	    return this.queries.getLastIndexedAt();
930	  }
931	
932	  /**
933	   * Completeness of the last full index run. `'complete'` is the only good
934	   * state. `'indexing'` after the fact means a run was killed mid-index (OOM,
935	   * SIGKILL, liveness watchdog) and the on-disk index is truncated;
936	   * `'partial'` means the run finished but silently dropped files
937	   * (discovered > indexed+skipped+errored); `'failed'` means it reported
938	   * failure. `null` = index predates this marker. Surfaced by
939	   * `codegraph status`.
940	   */
941	  getIndexState(): 'indexing' | 'complete' | 'partial' | 'failed' | null {
942	    const raw = this.queries.getMetadata('index_state');
943	    return raw === 'indexing' || raw === 'complete' || raw === 'partial' || raw === 'failed'
944	      ? raw
945	      : null;
946	  }
