948	  /**
949	   * Which engine built the current index: the package version + extraction
950	   * version stamped at the last full `indexAll`. Either field is null for an
951	   * index built before stamping existed (treated as stale). See
952	   * `extraction-version.ts` and `isIndexStale()`.
953	   */
954	  getIndexBuildInfo(): { version: string | null; extractionVersion: number | null } {
955	    const version = this.queries.getMetadata('indexed_with_version');
956	    const ev = this.queries.getMetadata('indexed_with_extraction_version');
957	    const parsed = ev != null ? parseInt(ev, 10) : NaN;
958	    return { version, extractionVersion: Number.isFinite(parsed) ? parsed : null };
959	  }
960	
961	  /**
962	   * True when the on-disk index was built by an engine whose extraction is
963	   * older than the one now running — i.e. a re-index would add data a migration
964	   * can't backfill. False when there's no index yet (nothing to refresh) or the
965	   * stamp is current. This is the signal behind `codegraph status`'s re-index
966	   * hint and `codegraph upgrade`'s reminder.
967	   */
968	  isIndexStale(): boolean {
969	    if (this.queries.getLastIndexedAt() == null) return false;
970	    const { extractionVersion } = this.getIndexBuildInfo();
971	    return extractionVersion == null || extractionVersion < EXTRACTION_VERSION;
972	  }
