981	  // ===========================================================================
982	  // Reference Resolution
983	  // ===========================================================================
984	
985	  /**
986	   * Resolve unresolved references and create edges
987	   *
988	   * This method takes unresolved references from extraction and attempts
989	   * to resolve them using multiple strategies:
990	   * - Framework-specific patterns (React, Express, Laravel)
991	   * - Import-based resolution
992	   * - Name-based symbol matching
993	   */
994	  resolveReferences(onProgress?: (current: number, total: number) => void): ResolutionResult {
995	    // Get all unresolved references from the database
996	    const unresolvedRefs = this.queries.getUnresolvedReferences();
997	    return this.resolver.resolveAndPersist(unresolvedRefs, onProgress);
998	  }
999	
1000	  /**
1001	   * Resolve references in batches to keep memory bounded on large codebases.
1002	   * Processes chunks of unresolved refs, persisting results after each batch.
1003	   */
1004	  async resolveReferencesBatched(onProgress?: (current: number, total: number) => void): Promise<ResolutionResult> {
1005	    return this.resolver.resolveAndPersistBatched(onProgress);
1006	  }
1007	
1008	  /**
1009	   * References extracted but never attempted by a resolution pass. Zero on a
1010	   * healthy index — a completed pass consumes every pending row (resolving it
