1111	  /**
1112	   * Graph-derived prompt matching for the front-load hook's MEDIUM tier:
1113	   * which indexed symbols do these prose words name? "state machine des
1114	   * commandes" → `OrderStateMachine`, in any human language whose technical
1115	   * nouns are Latin script — no keyword list involved.
1116	   *
1117	   * Precision comes from the repo's own naming statistics, not vocabulary:
1118	   * - CO-OCCURRENCE: ≥2 words that are segments of the SAME name ("state" +
1119	   *   "machine" → OrderStateMachine) is strong evidence and always qualifies.
1120	   * - RARITY: a single matched word qualifies only when its segment is
1121	   *   discriminative here (≤ {@link SEGMENT_RARITY_CEILING} distinct names) —
1122	   *   "checkout" in a shop backend yes, "state" in a react app no.
1123	   * Every candidate is re-verified against `nodes` before being returned
1124	   * (vocab rows are proposals; deletions leave orphans by design), so a
1125	   * returned symbol is guaranteed to exist right now.
1126	   */
1127	  getSegmentMatches(words: string[], limit: number = 6): SegmentMatch[] {
1128	    if (words.length === 0) return [];
1129	    // Variant → original word (plural folding), for coverage accounting.
1130	    const variantToWord = new Map<string, string>();
1131	    for (const word of words) {
1132	      for (const variant of segmentLookupVariants(word)) {
1133	        if (!variantToWord.has(variant)) variantToWord.set(variant, word);
1134	      }
1135	    }
1136	    const variants = [...variantToWord.keys()];
1137	
1138	    // Tier A: co-occurrence. The SQL folds variants back to their original
1139	    // word (#1146), so minWords=2 means two distinct PROMPT WORDS — a name
1140	    // matching both `service` and `services` can't tie with (or crowd past
1141	    // the LIMIT) a genuine two-word match. The JS re-check below recomputes
1142	    // the fold from live segments as the honesty layer.
1143	    const variantPairs = [...variantToWord.entries()].map(([segment, word]) => ({ segment, word }));
1144	    const candidates: Array<{ name: string; matchedWords: Set<string> }> = [];
1145	    for (const hit of this.queries.getSegmentCoOccurrence(variantPairs, 2, 24)) {
1146	      const matched = this.wordsMatchingName(hit.name, variantToWord);
1147	      if (matched.size >= 2) candidates.push({ name: hit.name, matchedWords: matched });
1148	    }
1149	
1150	    // Tier B: single rare word. Only when co-occurrence found nothing — a
1151	    // co-occurring name is categorically stronger evidence — and under
1152	    // stricter rules, because one word is thin: the word must be ≥5 chars
1153	    // (measured FPs: "this", "typo"); the segment must appear in AT LEAST TWO
1154	    // names (a concept the codebase is about clusters across names —
1155	    // CheckoutService/CheckoutController — while a prose coincidence is a
1156	    // singleton: measured FP "deploy to PRODUCTION" → the one name
1157	    // matchesNonProductionDir); and the candidate name must have ≥2 segments
1158	    // (a bare common verb matching a bare function name — "write" → `write` —
1159	    // is prose coincidence, not the user naming a symbol).
1160	    if (candidates.length === 0) {
1161	      const singleWordVariants = variants.filter((v) => variantToWord.get(v)!.length >= 5);
1162	      const counts = this.queries.getSegmentNameCounts(singleWordVariants);
1163	      const rare = [...counts.entries()]
1164	        .filter(([, n]) => n >= 2 && n <= CodeGraph.SEGMENT_RARITY_CEILING)
1165	        .sort((a, b) => a[1] - b[1])
1166	        .slice(0, 2);
1167	      for (const [variant] of rare) {
1168	        const word = variantToWord.get(variant)!;
1169	        for (const name of this.queries.getNamesForSegment(variant, 12)) {
1170	          if (splitIdentifierSegments(name).length < 2) continue;
1171	          candidates.push({ name, matchedWords: new Set([word]) });
1172	        }
1173	      }
1174	    }
1175	
1176	    // Verify against nodes (the honesty gate) and pick a representative
1177	    // definition per name. A name whose only nodes are file/import kind has
1178	    // no real definition to point at — surfacing the import statement instead
1179	    // reads as a matched symbol but isn't one (#1144) — so it's skipped, the
1180	    // same way an orphaned vocab row is. (Import names no longer enter the
1181	    // vocab at write time, but rows written before that exclusion persist
1182	    // until the next full index.)
1183	    const out: SegmentMatch[] = [];
1184	    const seen = new Set<string>();
1185	    candidates.sort((a, b) => b.matchedWords.size - a.matchedWords.size || a.name.length - b.name.length);
1186	    for (const candidate of candidates) {
1187	      if (out.length >= limit) break;
1188	      if (seen.has(candidate.name)) continue;
1189	      seen.add(candidate.name);
1190	      const nodes = this.queries.getNodesByName(candidate.name);
1191	      if (nodes.length === 0) continue; // orphaned vocab row — name no longer exists
1192	      const rep = nodes.find((n) => n.kind !== 'file' && n.kind !== 'import');
1193	      if (!rep) continue; // no real definition — don't surface an import/file as one
1194	      out.push({
1195	        name: candidate.name,
1196	        kind: rep.kind,
1197	        filePath: rep.filePath,
1198	        startLine: rep.startLine ?? 0,
1199	        matchedWords: [...candidate.matchedWords].sort(),
1200	      });
1201	    }
1202	    return out;
1203	  }
1204	
1205	  /** A single word ("state") can match hundreds of names in a big repo — that
1206	   *  is noise, not signal. Ceiling for the single-word tier; co-occurrence is
1207	   *  exempt because two words on one name is already discriminative. */
1208	  private static readonly SEGMENT_RARITY_CEILING = 25;
1209	
1210	  /** Which of the prompt's original words match `name`'s segments (via
1211	   *  variants). Segments are recomputed in JS — a name-keyed vocab lookup
1212	   *  would scan the (segment, name) primary key. */
1213	  private wordsMatchingName(name: string, variantToWord: Map<string, string>): Set<string> {
1214	    const segments = new Set(splitIdentifierSegments(name));
1215	    const matched = new Set<string>();
1216	    for (const [variant, word] of variantToWord) {
1217	      if (segments.has(variant)) matched.add(word);
1218	    }
1219	    return matched;
1220	  }
1221	
1222	  /**
1223	   * One-shot upgrade heal for callers that open the graph WITHOUT syncing —
1224	   * concretely the prompt hook, whose MEDIUM tier reads the segment
1225	   * vocabulary: a database migrated from before the vocab table existed
1226	   * starts with it empty, and the only other backfill lives inside `sync()`,
1227	   * which such callers never run (#1142). Returns true when the vocab is
1228	   * usable (already populated — the overwhelmingly common one-SELECT case —
1229	   * or healed here); false when it isn't (empty graph, or another process
1230	   * holds the index lock — that process's own sync heals it).
1231	   */
1232	  async healSegmentVocabIfEmpty(): Promise<boolean> {
1233	    const empty = (() => {
1234	      try { return this.queries.isNameSegmentVocabEmpty(); } catch { return false; }
1235	    })();
1236	    if (!empty) return true;
1237	    if (this.queries.getNodeAndEdgeCount().nodes === 0) return false;
1238	    return this.indexMutex.withLock(async () => {
1239	      try {
1240	        this.fileLock.acquire();
1241	      } catch {
1242	        return false; // an index/sync is running — it backfills the vocab itself
1243	      }
1244	      try {
1245	        if (!this.queries.isNameSegmentVocabEmpty()) return true; // raced: healed meanwhile
1246	        await this.rebuildNameSegmentVocab();
1247	        return true;
1248	      } finally {
1249	        this.fileLock.release();
1250	      }
1251	    });
1252	  }
1253	
1254	  /**
1255	   * Rebuild the segment vocabulary from the current graph, batched and
1256	   * yielding — the upgrade-heal path for indexes built before the vocab table
1257	   * existed. Runs inside the index mutex/lock (sync and
1258	   * healSegmentVocabIfEmpty hold them).
1259	   */
1260	  private async rebuildNameSegmentVocab(): Promise<void> {
1261	    const maybeYield = createYielder();
1262	    const BATCH = 2000;
1263	    for (let offset = 0; ; offset += BATCH) {
1264	      const names = this.queries.getDistinctNodeNames(BATCH, offset);
1265	      if (names.length === 0) break;
1266	      this.queries.insertNameSegmentsBatch(names);
1267	      await maybeYield();
1268	    }
1269	  }
