93	/** Last `::` / `.` / `/`-separated segment of a qualified symbol. */
94	function lastQualifierPart(symbol: string): string {
95	  const parts = symbol.split(/::|[./]/).filter((p) => p.length > 0);
96	  return parts[parts.length - 1] ?? symbol;
