99	/**
100	 * Normalize Erlang-native symbol spellings in an explore query into the shapes
101	 * the rest of the pipeline already understands. Agents working Erlang code
102	 * name symbols the way the language spells them — `mod:fn/3`, `init/2` — and
103	 * those tokens previously died in both consumers: the flow-builder's token
104	 * filter rejects `:` and `/arity` outright, and the search-side field parser
105	 * eats `mod:fn` as an unknown `field:value`. Measured on cowboy: the agent
106	 * named `cowboy_stream_h:request_process/3` in two queries, got no body back
107	 * either time, and fell back to Read.
108	 *
109	 *   - `fn/3` → `fn` (arity tail after an identifier; a path segment like
110	 *     `src/2fa` doesn't match because the tail must be all digits)
111	 *   - `mod:fn` → `mod.fn` (exactly one colon between identifiers, so it rides
112	 *     the existing Class.method qualified handling; `::`, URLs, drive letters,
113	 *     and times don't match, and the query language's own field prefixes —
114	 *     kind:/lang:/language:/path:/name: — are left alone)
115	 *
116	 * Safe cross-language: Lua's `t:m` spelling maps to the same `t.m` its
117	 * qualified names use, and no other supported spelling contains a bare
118	 * single-colon identifier pair.
119	 */
120	export function normalizeQuerySpelling(query: string): string {
121	  return query
122	    .replace(/\b([A-Za-z_][\w@]*)\/(\d{1,3})(?=$|[\s,()[\]/])/g, '$1')
123	    .replace(
124	      /(^|[\s,()[\]])(?!(?:kind|lang|language|path|name):)([a-z_][\w@]*):([A-Za-z_][\w@]*)(?=$|[\s,()[\]])/g,
125	      '$1$2.$3'
126	    );
127	}
