142	/**
143	 * Adaptive output budget for `codegraph_explore`, scaled to project size.
144	 *
145	 * Smaller codebases get a tighter total cap, fewer default files, smaller
146	 * per-file cap, and tighter clustering — so a focused query on a 100-file
147	 * project doesn't dump a whole file's worth of source into the agent's
148	 * context. Larger codebases keep the generous defaults because the
149	 * agent's native discovery cost (grep + find + many Reads) genuinely
150	 * dwarfs a fat explore call at that scale.
151	 *
152	 * Meta-text (relationships map, "additional relevant files" list,
153	 * completeness signal, budget note) is gated off for tiny projects
154	 * where one rich call is the whole story and the extra prose is just
155	 * overhead.
156	 *
157	 * Tier breakpoints mirror `getExploreBudget` so a project sits in the
158	 * same tier across both knobs.
159	 */
160	export interface ExploreOutputBudget {
161	  /** Hard cap on total output characters. */
162	  maxOutputChars: number;
163	  /** Default `maxFiles` when the caller didn't specify one. */
164	  defaultMaxFiles: number;
165	  /** Cap on contiguous source returned per file (across all its clusters). */
166	  maxCharsPerFile: number;
167	  /** Cluster gap threshold in lines — tighter clustering on small projects. */
168	  gapThreshold: number;
169	  /** Max symbols listed in the per-file header (``**`path`** — sym(kind), ...``). */
170	  maxSymbolsInFileHeader: number;
171	  /** Max edges shown per relationship kind in the Relationships section. */
172	  maxEdgesPerRelationshipKind: number;
173	  /** Include the "Relationships" section. */
174	  includeRelationships: boolean;
175	  /** Include the "Additional relevant files (not shown)" trailing list. */
176	  includeAdditionalFiles: boolean;
177	  /** Include the "Complete source code is included above…" reminder. */
178	  includeCompletenessSignal: boolean;
179	  /** Include the explore-budget reminder at the end. */
180	  includeBudgetNote: boolean;
181	  /**
182	   * Hard-drop test/spec/icon/i18n files from the relevant-file set unless
183	   * the query itself mentions tests. Today they're only deprioritized in
184	   * the sort, which on tiny repos still lets one slip into the top N (e.g.
185	   * cobra's `command_test.go` displaced `args.go` and contributed ~10KB of
186	   * pure noise to "How does cobra parse commands?"). Off by default; on
187	   * for the very-tiny tier where one slip dominates the budget.
188	   */
189	  excludeLowValueFiles: boolean;
190	}
191	
192	export function getExploreOutputBudget(fileCount: number): ExploreOutputBudget {
193	  // Tiered budget, scaled to project size. The budget is a CEILING (relevance
194	  // still gates WHAT is included), and it MUST stay under the agent's INLINE
195	  // tool-result cap (~25K chars). Above that, the host externalizes the result
196	  // to a file the agent then Reads back — re-introducing a read AND the
197	  // cache-write cost — which is exactly what a 35K vscode explore did in the
198	  // n=4 README A/B. So even large repos cap at ~24K: the answer is the handful
199	  // of ~100-line flow windows the agent would have grep-located and read (it
200	  // natively reads ~6–9 files, median 100-line ranges), NOT a sprawl of 12
201	  // files. Concentration onto the flow emerges from this cap + the named-file-
202	  // first sort dropping peripheral files. Invariant: a larger tier must never
203	  // get a smaller `maxCharsPerFile` than a smaller tier.
204	  if (fileCount < 150) {
205	    return {
206	      // ITER3: revert iter2's aggressive body shrink (forced Read fallback —
207	      // the per-file 2.5K cap pushed the agent to Read instead of node).
208	      // Back to the iter1 shape (13K/4/3.8K) but keep the test-file
209	      // hard-exclude. The cost lever for this tier lives in steering the
210	      // agent to stop after 1-2 calls, not in this budget.
211	      maxOutputChars: 13000,
212	      defaultMaxFiles: 4,
213	      maxCharsPerFile: 3800,
214	      gapThreshold: 7,
215	      maxSymbolsInFileHeader: 5,
216	      maxEdgesPerRelationshipKind: 4,
217	      includeRelationships: false,
218	      includeAdditionalFiles: false,
219	      includeCompletenessSignal: false,
220	      includeBudgetNote: false,
221	      excludeLowValueFiles: true,
222	    };
223	  }
224	  if (fileCount < 500) {
225	    return {
226	      // ITER3: same revert/keep-filter pattern as <150.
227	      maxOutputChars: 18000,
228	      defaultMaxFiles: 5,
229	      maxCharsPerFile: 3800,
230	      gapThreshold: 8,
231	      maxSymbolsInFileHeader: 6,
232	      maxEdgesPerRelationshipKind: 6,
233	      includeRelationships: false,
234	      includeAdditionalFiles: false,
235	      includeCompletenessSignal: false,
236	      includeBudgetNote: false,
237	      excludeLowValueFiles: true,
238	    };
239	  }
240	  if (fileCount < 5000) {
241	    return {
242	      // ~150-line per-file window (the native read unit) × ~6 files, capped at
243	      // the ~24K inline ceiling so the response is never externalized. Per-file
244	      // stays ≥ the <500 tier (3800) — monotonic.
245	      maxOutputChars: 24000,
246	      defaultMaxFiles: 8,
247	      maxCharsPerFile: 6500,
248	      gapThreshold: 12,
249	      maxSymbolsInFileHeader: 10,
250	      maxEdgesPerRelationshipKind: 10,
251	      includeRelationships: true,
252	      includeAdditionalFiles: true,
253	      includeCompletenessSignal: true,
254	      includeBudgetNote: true,
255	      excludeLowValueFiles: false,
256	    };
257	  }
258	  // Large + very-large repos: SAME ~24K inline ceiling (a bigger response just
259	  // externalizes — see vscode). More files indexed → more CALLS via
260	  // getExploreBudget, not a bigger single response. Per-file 7000 (≥ smaller
261	  // tiers) gives the central file a ~180-line orientation window.
262	  if (fileCount < 15000) {
263	    return {
264	      maxOutputChars: 24000,
265	      defaultMaxFiles: 8,
266	      maxCharsPerFile: 7000,
267	      gapThreshold: 15,
268	      maxSymbolsInFileHeader: 15,
269	      maxEdgesPerRelationshipKind: 15,
270	      includeRelationships: true,
271	      includeAdditionalFiles: true,
272	      includeCompletenessSignal: true,
273	      includeBudgetNote: true,
274	      excludeLowValueFiles: false,
275	    };
276	  }
277	  return {
278	    maxOutputChars: 24000,
279	    defaultMaxFiles: 8,
280	    maxCharsPerFile: 7000,
281	    gapThreshold: 15,
282	    maxSymbolsInFileHeader: 15,
283	    maxEdgesPerRelationshipKind: 15,
284	    includeRelationships: true,
285	    includeAdditionalFiles: true,
286	    includeCompletenessSignal: true,
287	    includeBudgetNote: true,
288	    excludeLowValueFiles: false,
289	  };
290	}
