292	/**
293	 * Whether `codegraph_explore` should prefix source lines with their line
294	 * numbers (cat -n style: `<num>\t<code>`).
295	 *
296	 * Line numbers let the agent cite `file:line` straight from the explore
297	 * payload instead of re-Reading the file just to find a line number — the
298	 * dominant residual cost on precise-tracing questions (#185 follow-up).
299	 *
300	 * Defaults ON. Set `CODEGRAPH_EXPLORE_LINENUMS=0` to disable (used by the
301	 * A/B harness to measure the payload-cost vs. read-savings tradeoff).
302	 */
303	function exploreLineNumbersEnabled(): boolean {
304	  return process.env.CODEGRAPH_EXPLORE_LINENUMS !== '0';
305	}
