307	/**
308	 * Adaptive explore sizing (default ON). `codegraph_explore` skeletonizes OFF-SPINE
309	 * polymorphic-sibling files — a file whose class is one of ≥3 interchangeable
310	 * implementations of a shared interface (e.g. OkHttp's `: Interceptor` classes) —
311	 * to class + member signatures (bodies elided), keeping the on-spine exemplar full.
312	 * This sizes the response to the answer instead of the budget cap on sibling-heavy
313	 * flows (OkHttp interceptor-chain explore 28.5k→16.6k, ~28% cheaper than native
314	 * search, reads flat). It is PROVABLY INERT elsewhere: distinct pipeline steps (no
315	 * ≥3-implementer supertype, e.g. Excalidraw's `renderStaticScene`) and on-spine
316	 * files keep full source — output is byte-identical to shipped on excalidraw /
317	 * tokio / django / vscode / gin. Set `CODEGRAPH_ADAPTIVE_EXPLORE=0` to disable.
318	 */
319	function adaptiveExploreEnabled(): boolean {
320	  return process.env.CODEGRAPH_ADAPTIVE_EXPLORE !== '0' && process.env.CODEGRAPH_ADAPTIVE_EXPLORE !== 'false';
321	}
