323	/**
324	 * How long the FIRST tool call waits on the post-open catch-up reconcile before
325	 * giving up and serving anyway (issue #905). On a normal repo the reconcile
326	 * finishes in well under this, so the gate is fully honored and nothing changes.
327	 * On a very large repo (~100k files) the reconcile takes minutes — blocking the
328	 * first call on all of it presents as a multi-minute hang — so we wait briefly
329	 * for a clean answer, then serve and let the reconcile finish in the background
330	 * (it yields to the event loop, so a concurrent read still runs).
331	 *
332	 * `CODEGRAPH_CATCHUP_GATE_TIMEOUT_MS` overrides the default; `0` restores the
333	 * old unbounded-wait behavior (always block until the reconcile completes).
334	 */
335	const DEFAULT_CATCHUP_GATE_TIMEOUT_MS = 3000;
336	function resolveCatchUpGateTimeoutMs(): number {
337	  const raw = process.env.CODEGRAPH_CATCHUP_GATE_TIMEOUT_MS;
338	  if (raw === undefined || raw === '') return DEFAULT_CATCHUP_GATE_TIMEOUT_MS;
339	  const n = Number(raw);
340	  if (!Number.isFinite(n) || n < 0) return DEFAULT_CATCHUP_GATE_TIMEOUT_MS;
341	  return Math.floor(n);
342	}
