361	/**
362	 * Unique line-prefix for a per-file source section in codegraph_explore output.
363	 * Issue #778: tool results dropped ATX headings (`####`, `##`, `###`) for bold
364	 * labels so Markdown-rendering MCP clients (e.g. the Claude Code VSCode
365	 * extension) stop blowing every header up to H1–H4. The path is bold + a code
366	 * span so it still reads as a header, and the leading ``**` `` stays a UNIQUE,
367	 * greppable marker — no other explore line begins with it — that the explore
368	 * truncation boundary (`handleExplore`) keys off to cut on whole file sections.
369	 */
370	const FILE_SECTION_PREFIX = '**`';
371	// Placeholder for codegraph_explore's "Found N symbols across M files." line.
372	// The honest N/M can only be known after the final truncation drops trailing
