383	/**
384	 * Per-file staleness banner emitted at the top of a tool response when the
385	 * file watcher has pending events for files referenced by the response.
386	 * The agent uses this to fall back to Read for those specific files
387	 * without waiting for the debounced sync (issue #403).
388	 */
389	export function formatStaleBanner(stale: PendingFile[]): string {
390	  const now = Date.now();
391	  const lines = stale.map((p) => {
392	    const ageMs = Math.max(0, now - p.lastSeenMs);
393	    const label = p.indexing ? 'indexing in progress' : 'pending sync';
394	    return `  - ${p.path} (edited ${ageMs}ms ago, ${label})`;
395	  });
396	  return (
397	    '⚠️ Some files referenced below were edited since the last index sync — ' +
398	    'their codegraph entries may be stale:\n' +
399	    lines.join('\n') +
400	    '\nFor accurate content of those specific files, Read them directly. ' +
401	    'The rest of this response is fresh.'
402	  );
403	}
404	
405	/**
406	 * Compact footer listing pending files that are NOT referenced in this
407	 * response. Gives the agent a complete project-wide freshness picture
408	 * without bloating the main banner.
409	 */
410	export function formatStaleFooter(stale: PendingFile[]): string {
411	  const MAX = 5;
412	  const now = Date.now();
413	  const shown = stale.slice(0, MAX);
414	  const lines = shown.map((p) => {
415	    const ageMs = Math.max(0, now - p.lastSeenMs);
416	    return `  - ${p.path} (edited ${ageMs}ms ago)`;
417	  });
418	  const more = stale.length > MAX ? `\n  - …and ${stale.length - MAX} more` : '';
419	  return (
420	    `(Note: ${stale.length} file(s) elsewhere in this project are pending index ` +
421	    `sync but were not referenced above:\n${lines.join('\n')}${more})`
422	  );
423	}
