425	/**
426	 * Whole-index degradation banner (issue #876). Emitted at the top of a read
427	 * tool response when live watching has permanently stopped — at which point
428	 * `getPendingFiles()` is empty, so the per-file banner above can't fire even
429	 * though the index is now FROZEN and silently drifting stale. Leads with the
430	 * agent-actionable instruction (Read directly) and carries the reason, which
431	 * already names the operator remedy (`codegraph sync` / git hooks).
432	 */
433	export function formatDegradedBanner(reason: string | null): string {
434	  return (
435	    '⚠️ CodeGraph auto-sync is DISABLED — live file watching stopped, so the index is ' +
436	    'frozen and any file edited since then is stale here. Read files directly to confirm ' +
437	    'current content before relying on it.' +
438	    (reason ? `\n  Reason: ${reason}` : '')
439	  );
440	}
