1097	    // path. One key per instance means closeAll() closes each exactly once, and
1098	    // a changed resolution maps to a different entry instead of a stale hit.
1099	    const cached = this.projectCache.get(resolvedRoot);
1100	    if (cached) return this.freshen(cached);
1101	
1102	    const cg = loadCodeGraph().openSync(resolvedRoot);
1103	    this.projectCache.set(resolvedRoot, cg);
1104	    return cg;
1105	  }
