1247	  /**
1248	   * Annotate a successful read-tool result with per-file staleness — the
1249	   * non-blocking answer to issue #403. The file watcher tracks every event
1250	   * it sees per path; here we intersect "files referenced in this response"
1251	   * against that pending set and prepend a compact banner so the agent can
1252	   * fall back to Read for those *specific* files without waiting for the
1253	   * debounced sync to fire. Other pending files in the project (not
1254	   * referenced by this response) get a small footer so the agent has a
1255	   * complete picture without bloating the banner.
1256	   *
1257	   * Cost when nothing is pending — the common case — is one boolean check.
1258	   * No I/O, no parsing of markdown beyond a per-pending-file substring scan.
1259	   */
1260	  private withStalenessNotice(result: ToolResult, projectPath?: string): ToolResult {
1261	    if (result.isError) return result;
1262	
1263	    let cg: CodeGraph;
1264	    try {
1265	      cg = this.getCodeGraph(projectPath);
1266	    } catch {
1267	      return result; // no default project — leave as is
1268	    }
1269	
1270	    // Cross-project `projectPath` calls open a cached CodeGraph WITHOUT a
1271	    // watcher (watchers are only attached to the default session project).
1272	    // When the cross-project path happens to be the same project as the
1273	    // default cg, the cached instance is the wrong one — its pendingFiles is
1274	    // permanently empty. Detect the equal-path case and prefer the default
1275	    // cg so the staleness signal still fires when an agent passes the
1276	    // explicit projectPath form of its own project.
1277	    if (this.cg && cg !== this.cg) {
1278	      try {
1279	        const sameProject =
1280	          resolvePath(this.cg.getProjectRoot()) === resolvePath(cg.getProjectRoot());
1281	        if (sameProject) cg = this.cg;
1282	      } catch {
1283	        /* getProjectRoot may throw on a closed instance — leave cg as is */
1284	      }
1285	    }
1286	
1287	    // Whole-index degradation (#876): once live watching has permanently
1288	    // stopped, getPendingFiles() is empty so the per-file banner below can't
1289	    // fire — but the index is now FROZEN and silently drifting stale. Surface
1290	    // one global notice instead, so the agent Reads for current content rather
1291	    // than trusting a response off a no-longer-updating index. (Cross-project
1292	    // calls open a watcher-less CodeGraph, so this is false there — correct: we
1293	    // only know degraded state for the default session project.)
1294	    let degraded = false;
1295	    try {
1296	      degraded = cg.isWatcherDegraded?.() ?? false;
1297	    } catch {
1298	      degraded = false;
1299	    }
1300	    if (degraded) {
1301	      const [head, ...tail] = result.content;
1302	      if (!head || head.type !== 'text') return result;
1303	      let reason: string | null = null;
1304	      try {
1305	        reason = cg.getWatcherDegradedReason?.() ?? null;
1306	      } catch {
1307	        reason = null;
1308	      }
1309	      const composed = `${formatDegradedBanner(reason)}\n\n${head.text}`;
1310	      return { ...result, content: [{ type: 'text', text: composed }, ...tail] };
1311	    }
1312	
1313	    // Defensive: some test fakes inject a partial CodeGraph stub without the
1314	    // newer pending-files API. Treat missing/throwing as "no pending files."
1315	    let pending: PendingFile[] = [];
1316	    try {
1317	      pending = cg.getPendingFiles?.() ?? [];
1318	    } catch {
1319	      return result;
1320	    }
1321	    if (pending.length === 0) return result;
1322	
1323	    const [first, ...rest] = result.content;
1324	    if (!first || first.type !== 'text') return result;
1325	
1326	    const text = first.text;
1327	    const inResponse: PendingFile[] = [];
1328	    const elsewhere: PendingFile[] = [];
1329	    for (const p of pending) {
1330	      // Substring match against the project-relative POSIX path — that's
1331	      // exactly the format both the watcher and every codegraph response
1332	      // emit, so a plain includes() is sufficient and avoids regex pitfalls.
1333	      if (text.includes(p.path)) inResponse.push(p);
1334	      else elsewhere.push(p);
1335	    }
1336	
1337	    let banner = '';
1338	    if (inResponse.length > 0) {
1339	      banner = formatStaleBanner(inResponse);
1340	    }
1341	    let footer = '';
1342	    if (elsewhere.length > 0) {
1343	      footer = formatStaleFooter(elsewhere);
1344	    }
1345	    if (!banner && !footer) return result;
1346	
1347	    const composed = [banner, text, footer].filter(Boolean).join('\n\n');
1348	    return { ...result, content: [{ type: 'text', text: composed }, ...rest] };
1349	  }
