1440	  /**
1441	   * Run a single read tool to completion and return its raw {@link ToolResult},
1442	   * classifying expected failures the same way {@link execute}'s catch does so
1443	   * the SHAPE is identical whether dispatch runs in-process or on a worker:
1444	   * NotIndexed → success-shaped guidance, PathRefusal → clean error, anything
1445	   * else → internal-error-with-retry. Never throws.
1446	   *
1447	   * This is the worker thread's entry point (see {@link ./query-worker}) and the
1448	   * in-process fallback for {@link execute}. It deliberately does NOT run the
1449	   * catch-up gate or the staleness/worktree notices — those need the daemon's
1450	   * watched main instance and stay on the main thread. Cross-cutting allowlist +
1451	   * path validation already ran in {@link execute} before routing here.
1452	   */
1453	  async executeReadTool(toolName: string, args: Record<string, unknown>): Promise<ToolResult> {
1454	    try {
1455	      return await this.dispatchTool(toolName, args);
1456	    } catch (err) {
1457	      if (err instanceof NotIndexedError) {
1458	        return this.textResult(err.message);
1459	      }
1460	      if (err instanceof PathRefusalError) {
1461	        return this.errorResult(err.message);
1462	      }
1463	      return this.errorResult(
1464	        `Tool execution failed: ${err instanceof Error ? err.message : String(err)}. ` +
1465	        'This is an internal codegraph error — retry the call once; if it persists, ' +
1466	        'continue without codegraph for this task.'
1467	      );
1468	    }
1469	  }
