1645	  private async handleCallees(args: Record<string, unknown>): Promise<ToolResult> {
1646	    const symbol = this.validateString(args.symbol, 'symbol');
1647	    if (typeof symbol !== 'string') return symbol;
1648	
1649	    const cg = this.getCodeGraph(args.projectPath as string | undefined);
1650	    const limit = clamp((args.limit as number) || 20, 1, 100);
1651	    const fileFilter = typeof args.file === 'string' ? args.file : undefined;
1652	
