1693	    const lines: string[] = [
1694	      `**Callees of ${symbol} — ${groups.length} distinct definitions (narrow with \`file\`)**`,
1695	    ];
1696	    for (const group of groups) {
1697	      const { callees, labels } = collect(group);
1698	      lines.push('', this.definitionHeading(group));
