1868	  /**
1869	   * Flow-from-named-symbols: an agent's codegraph_explore query is a bag of
1870	   * symbol names that usually spans the flow it's investigating (e.g.
1871	   * "PmsProductController getList PmsProductService list PmsProductServiceImpl").
1872	   * Surface the longest call chain AMONG those named symbols — scoped to what the
1873	   * agent explicitly named, so (unlike a fuzzy relevance set) there's no
1874	   * wrong-feature wandering. Rides synthesized edges, so controller→service-
1875	   * interface→impl shows up. Returns '' if no chain of >=3 nodes exists.
1876	   *
1877	   * Ambiguous tokens (Java `list` → dozens of nodes) are disambiguated by
1878	   * CO-NAMING: the agent names the class too, so we keep only `list` candidates
1879	   * whose qualifiedName contains another named token (`PmsProductServiceImpl::list`),
1880	   * dropping unrelated `OmsOrderService::list`.
1881	   */
1882	  private buildFlowFromNamedSymbols(cg: CodeGraph, query: string): { text: string; pathNodeIds: Set<string>; namedNodeIds: Set<string>; uniqueNamedNodeIds: Set<string>; spineCallSites: Map<string, number> } {
1883	    // spineCallSites: for each spine node, the line where it CALLS the next hop —
1884	    // lets the source assembler window an oversize spine method (e.g. n8n's 962-line
1885	    // processRunExecutionData) to the call site instead of dumping the whole body.
1886	    const EMPTY = { text: '', pathNodeIds: new Set<string>(), namedNodeIds: new Set<string>(), uniqueNamedNodeIds: new Set<string>(), spineCallSites: new Map<string, number>() };
1887	    try {
1888	      const CALLABLE = new Set(['method', 'function', 'component', 'constructor']);
1889	      // Strip only a REAL file extension (Create.cs → Create); KEEP qualified
1890	      // names (Class.method / Class::method) — the agent's most precise input,
1891	      // resolved exactly by findAllSymbols. (The old strip mangled Class.method
1892	      // into Class, throwing the method away.)
1893	      const FILE_EXT = /\.(?:java|kt|kts|ts|tsx|js|jsx|mjs|cjs|cs|py|go|rb|php|swift|rs|cpp|cc|cxx|c|h|hpp|scala|lua|dart|vue|svelte|astro|erl|hrl)$/i;
1894	      const tokens = [...new Set(
1895	        query.split(/[\s,()[\]]+/)
1896	          .map((t) => t.replace(FILE_EXT, '').trim())
1897	          .filter((t) => t.length >= 3 && /^[A-Za-z_$][\w$]*(?:(?:::|\.)[\w$]+)*$/.test(t))
1898	      )].slice(0, 16);
1899	      if (tokens.length < 2) return EMPTY;
1900	      // Pool of name SEGMENTS (Class + method from every token) used to
1901	      // disambiguate an ambiguous SIMPLE name: keep a candidate only if its
1902	      // CONTAINER class is itself named in the query.
1903	      const segPool = new Set<string>();
1904	      for (const t of tokens) for (const s of t.toLowerCase().split(/::|\./)) if (s) segPool.add(s);
1905	      const named = new Map<string, Node>();
1906	      // Nodes whose token is SPECIFIC — a (near-)unique callable name (<=3 defs in
1907	      // the whole graph). These are safe to SPARE a file on: the agent named THIS
1908	      // method (`getResponseWithInterceptorChain`, 1 def). A hyper-polymorphic name
1909	      // (`as_sql`, 110 defs across every Expression/Compiler subclass) is NOT here,
1910	      // so naming it doesn't keep every backend variant full and flood the budget.
1911	      const uniqueNamedNodeIds = new Set<string>();
1912	      // token → resolved node ids: drives the token-coverage check that gates
1913	      // the dynamic-boundary scan (a token is covered when ANY of its nodes
1914	      // lands on the main chain — overloads off the chain don't count against).
1915	      const tokenNodes = new Map<string, string[]>();
1916	      // token → its full same-name callable family (before the container filter).
