1921	      // edge. RTK thunks are `const X = createAsyncThunk(...)`, so a thunk→thunk hop
1922	      // is constant→constant — the CALLABLE-only `named` set can't hold it, and
1923	      // without this the hop is invisible to the Flow path at every tier (the
1924	      // Relationships section catches it only on repos ≥500 files). Kept SEPARATE
1925	      // from `named` (which drives the call-chain + source sizing, callable-only);
1926	      // fed only to the dynamic-dispatch-links scan below.
1927	      const dynNamed = new Map<string, Node>();
1928	      const DYN_KINDS = new Set(['constant', 'variable', 'field', 'property']);
1929	      const hasHeuristicEdge = (id: string): boolean =>
1930	        [...cg.getCallers(id), ...cg.getCallees(id)].some(({ edge }) => edge.provenance === 'heuristic');
1931	      for (const t of tokens) {
1932	        const hits = this.findAllSymbols(cg, t).nodes;
1933	        const cands = hits.filter((n) => CALLABLE.has(n.kind));
1934	        tokenFamily.set(t, cands);
1935	        // A qualified or otherwise-specific name (<=3 hits) keeps all; an
1936	        // ambiguous simple name keeps only candidates whose container is named.
1937	        const specific = cands.length <= 3;
1938	        const pick = specific
1939	          ? cands
1940	          : cands.filter((n) => {
1941	              const segs = (n.qualifiedName || '').toLowerCase().split(/::|\./).filter(Boolean);
1942	              const container = segs.length >= 2 ? segs[segs.length - 2] : '';
1943	              return !!container && segPool.has(container);
