1945	        const kept = pick.slice(0, 6);
1946	        tokenNodes.set(t, kept.map((n) => n.id));
1947	        for (const n of kept) {
1948	          named.set(n.id, n);
1949	          if (specific) uniqueNamedNodeIds.add(n.id);
1950	        }
1951	        // Same token, non-callable synth endpoints (capped, precision-gated on an
1952	        // actual heuristic edge so plain config constants never qualify).
1953	        // Per-token sub-cap so one token's many endpoints (10 nix option writes
1954	        // of `programs.git.enable` across test configs) can't fill the pool
1955	        // before later tokens (`home.file`) get a slot.
1956	        if (dynNamed.size < 12) {
1957	          let tokenDyn = 0;
1958	          for (const n of hits) {
1959	            if (CALLABLE.has(n.kind) || !DYN_KINDS.has(n.kind) || dynNamed.has(n.id)) continue;
