1964	            if (dynNamed.size >= 12 || tokenDyn >= 4) break;
1965	          }
1966	        }
1967	        if (named.size > 40) break;
1968	      }
1969	      // Surface synthesized (heuristic) edges incident to a named symbol — INCLUDING
1970	      // the non-callable CONSTANT endpoints in `dynNamed`. `skipInChain` drops a hop
1971	      // already shown in the rendered main chain (a 2-node chain renders nothing, so a
1972	      // direct named→named synth hop still surfaces — #687).
1973	      const collectSynthLinks = (skipInChain: ((e: Edge) => boolean) | null): string[] => {
1974	        const synthLines: string[] = [];
1975	        const synthSeen = new Set<string>();
1976	        for (const n of [...named.values(), ...dynNamed.values()]) {
1977	          if (synthLines.length >= 6) break;
1978	          for (const { node: other, edge } of [...cg.getCallers(n.id), ...cg.getCallees(n.id)]) {
