1980	            if (edge.provenance !== 'heuristic' || other.id === n.id) continue;
1981	            if (skipInChain && skipInChain(edge)) continue;
1982	            const src = edge.source === n.id ? n : other;
1983	            const tgt = edge.source === n.id ? other : n;
1984	            const key = `${src.name}>${tgt.name}`;
1985	            if (synthSeen.has(key)) continue;
1986	            synthSeen.add(key);
1987	            const note = this.synthEdgeNote(edge);
1988	            synthLines.push(`- ${src.name} → ${tgt.name}   [${note ? note.compact : edge.kind}]`);
1989	          }
1990	        }
1991	        return synthLines;
1992	      };
1993	      if (named.size < 2) {
1994	        // <2 CALLABLES resolved. Two recoveries before giving up: (1) synthesized
1995	        // edges among named CONSTANT/VARIABLE endpoints — RTK thunk→thunk is
1996	        // constant→constant, so `named` can be empty while `dynNamed` holds the
1997	        // whole chain; (2) the one resolved callable's body may hold the
1998	        // dynamic-dispatch site that EXPLAINS a half-connected flow.
1999	        const synthLines = collectSynthLinks(null);
2000	        const boundaries = named.size === 0 ? '' : (this.buildDynamicBoundaries(cg, [...named.values()], named) || '');
2001	        if (synthLines.length === 0 && !boundaries) return EMPTY;
2002	        const out: string[] = [];
2003	        if (synthLines.length) out.push(
2004	          '**Dynamic-dispatch links among your symbols**',
2005	          '(synthesized — the indirect hops grep/Read would reconstruct; the `@file:line` is the wiring site)',
2006	          '', ...synthLines, '');
2007	        if (boundaries) out.push(boundaries);
2008	        out.push('> Full source for these symbols is below.\n');
2009	        return { text: out.join('\n'), pathNodeIds: new Set(), namedNodeIds: new Set<string>([...named.keys(), ...dynNamed.keys()]), uniqueNamedNodeIds, spineCallSites: new Map<string, number>() };
2010	      }
2011	      const MAX_HOPS = 7;
2012	      let best: Array<{ node: Node; edge: Edge | null }> | null = null;
2013	      // BFS the full call graph (incl. synth edges) from each named seed, but
2014	      // only ACCEPT a sink that is also named — both ends anchored to symbols the
2015	      // agent named, so the chain stays on-topic while bridging intermediates
2016	      // (e.g. the exact interface overload) that the token resolution missed.
2017	      for (const seed of [...named.values()].slice(0, 8)) {
2018	        const parent = new Map<string, { prev: string | null; edge: Edge | null; node: Node }>();
2019	        parent.set(seed.id, { prev: null, edge: null, node: seed });
2020	        const q: Array<{ id: string; depth: number; streak: number }> = [{ id: seed.id, depth: 0, streak: 0 }];
2021	        let deep: string | null = null, deepDepth = 0;
2022	        const MAX_BRIDGE = 1; // ≤1 consecutive UNNAMED hop: bridge one missing intermediate, never wander a god-function's fan-out
2023	        for (let h = 0; h < q.length && parent.size < 1500; h++) {
2024	          const { id, depth, streak } = q[h]!;
2025	          if (id !== seed.id && named.has(id) && depth > deepDepth) { deep = id; deepDepth = depth; }
