2028	            if (c.edge.kind !== 'calls' || parent.has(c.node.id)) continue;
2029	            const newStreak = named.has(c.node.id) ? 0 : streak + 1;
2030	            if (newStreak > MAX_BRIDGE) continue;
2031	            parent.set(c.node.id, { prev: id, edge: c.edge, node: c.node });
