2246	        try {
2247	          sups = cg.getOutgoingEdges(container.id)
2248	            .filter((e) => e.kind === 'implements' || e.kind === 'extends')
2249	            .map((e) => { try { return cg.getNode(e.target); } catch { return null; } })
