3662	    // vscode explore did exactly this in the n=4 A/B). So allow a little
3663	    // necessary overflow above the 24K budget, but hard-stop at 25K — never into
3664	    // externalize territory.
3665	    const output = flow.text + lines.join('\n');
3666	
3667	    const hardCeiling = Math.min(Math.round(budget.maxOutputChars * 1.5), 25000);
3668	    let finalText: string;
3669	    if (output.length > hardCeiling) {
3670	      // Cut at a FILE-SECTION boundary (the last ``**` `` file header before the
3671	      // ceiling) so we drop whole trailing file-sections rather than slicing
3672	      // through a method body — a half-rendered method just forces the Read this
3673	      // tool exists to prevent. Fall back to a line boundary only if no section
3674	      // header sits in the back half (degenerate single-giant-section case).
3675	      const cut = output.slice(0, hardCeiling);
3676	      const lastSection = cut.lastIndexOf('\n' + FILE_SECTION_PREFIX);
3677	      const boundary = lastSection > hardCeiling * 0.5 ? lastSection : cut.lastIndexOf('\n');
3678	      const safe = boundary > 0 ? cut.slice(0, boundary) : cut;
3679	      finalText = safe + '\n\n... (output truncated to budget; the source above is complete and verbatim — treat it as already Read. For any area not covered, run another codegraph_explore with the specific names — do NOT Read these files.)';
3680	    } else {
3681	      finalText = output;
3682	    }
3683	
3684	    // Curated header (#1046): substitute the sentinel with the count of files
3685	    // whose source SURVIVES in the final text — not `subgraph`/`fileGroups` (the
3686	    // raw gather a broad query inflates) and not `filesIncluded` (which can
3687	    // over-count when the ceiling above drops trailing sections). A file counts
3688	    // only if its section header is still present; its relevant (non-import)
3689	    // symbols are summed for N. Files we couldn't fit are still named under "Not
3690	    // shown above" + the budget note, so nothing is silently dropped.
3691	    const survivors = renderedFilePaths.filter((fp) =>
3692	      finalText.includes(`${FILE_SECTION_PREFIX}${fp}\``));
3693	    const shownSymbols = survivors.reduce((sum, fp) => {
3694	      const g = fileGroups.get(fp);
3695	      if (!g) return sum;
3696	      return sum + new Set(
3697	        g.nodes.filter((n) => n.kind !== 'import' && n.kind !== 'export').map((n) => n.id),
3698	      ).size;
3699	    }, 0);
3700	    const summaryLine = survivors.length > 0
3701	      ? `Found ${shownSymbols} symbol${shownSymbols === 1 ? '' : 's'} across ${survivors.length} file${survivors.length === 1 ? '' : 's'}.`
3702	      : `Found ${subgraph.nodes.size} symbol${subgraph.nodes.size === 1 ? '' : 's'} across ${fileGroups.size} file${fileGroups.size === 1 ? '' : 's'}.`;
3703	    finalText = finalText.replace(SUMMARY_SENTINEL, summaryLine);
3704	
3705	    return this.textResult(finalText);
3706	  }
