3708	  /**
3709	   * Handle codegraph_node
3710	   */
3711	  private async handleNode(args: Record<string, unknown>): Promise<ToolResult> {
3712	    const cg = this.getCodeGraph(args.projectPath as string | undefined);
3713	    // Default to false to minimize context usage
3714	    const includeCode = args.includeCode === true;
3715	    const fileHint = typeof args.file === 'string' && args.file.trim() ? args.file.trim() : undefined;
3716	    const lineHint = typeof args.line === 'number' && args.line > 0 ? args.line : undefined;
3717	    const offset = typeof args.offset === 'number' && args.offset > 0 ? Math.floor(args.offset) : undefined;
3718	    const limit = typeof args.limit === 'number' && args.limit > 0 ? Math.floor(args.limit) : undefined;
3719	    const symbolsOnly = args.symbolsOnly === true;
3720	    const symbolRaw = typeof args.symbol === 'string' ? args.symbol.trim() : '';
3721	
3722	    // FILE READ MODE: a `file` with no `symbol` reads that file like the Read
3723	    // tool — its current on-disk source with line numbers, narrowable with
3724	    // `offset`/`limit` exactly as Read does — PLUS a one-line blast-radius
3725	    // header (which files depend on it). `symbolsOnly` returns just the
3726	    // structural map instead. Backed by the index: same bytes Read gives you.
3727	    if (!symbolRaw && fileHint) {
3728	      return this.handleFileView(cg, fileHint, { offset, limit, symbolsOnly });
3729	    }
3730	
3731	    const symbol = this.validateString(args.symbol, 'symbol');
3732	    if (typeof symbol !== 'string') return symbol;
3733	
3734	    let matches = this.findSymbolMatches(cg, symbol);
3735	    if (matches.length === 0) {
3736	      return this.textResult(`Symbol "${symbol}" not found in the codebase`);
3737	    }
3738	
3739	    // Disambiguate a heavily-overloaded name to a specific definition the caller
3740	    // pinned by file/line (the `file:line` a trail or another tool showed it) —
3741	    // so it can fetch e.g. `Harness::poll` at harness.rs:153 out of 50+ `poll`s
3742	    // instead of Reading. file matches by path suffix/substring; line prefers the
3743	    // def whose body contains it, else the nearest start. Only narrows (never
3744	    // empties — if a hint matches nothing it's ignored).
3745	    if (matches.length > 1 && (fileHint || lineHint !== undefined)) {
3746	      const norm = (p: string) => p.replace(/\\/g, '/').toLowerCase();
3747	      let narrowed = matches;
3748	      if (fileHint) {
3749	        const fh = norm(fileHint);
3750	        const byFile = narrowed.filter((n) => norm(n.filePath).endsWith(fh) || norm(n.filePath).includes(fh));
3751	        if (byFile.length > 0) narrowed = byFile;
3752	      }
3753	      if (lineHint !== undefined && narrowed.length > 1) {
3754	        const containing = narrowed.filter((n) => n.startLine <= lineHint && (n.endLine ?? n.startLine) >= lineHint);
3755	        narrowed = containing.length > 0
3756	          ? containing
3757	          : [...narrowed].sort((a, b) => Math.abs(a.startLine - lineHint) - Math.abs(b.startLine - lineHint)).slice(0, 1);
3758	      }
3759	      if (narrowed.length > 0) matches = narrowed;
3760	    }
3761	
3762	    // Single definition — the common case.
3763	    if (matches.length === 1) {
3764	      return this.textResult(this.truncateOutput(await this.renderNodeSection(cg, matches[0]!, includeCode)));
3765	    }
3766	
3767	    // Multiple definitions share this name — overloads, or same-named methods on
3768	    // different types (Alamofire `didCompleteTask`/`task`/`validate`, gin
3769	    // `reset`). Returning ONE forces the agent to guess, and when it guesses
3770	    // wrong it READS the file to find the right overload — the dominant
3771	    // codegraph_node read cause on Swift/Go. So return them ALL: pack as many
3772	    // FULL bodies as fit a char budget (the agent gets the one it needs in this
3773	    // one call, no follow-up parameter to learn), and list any remainder by
3774	    // file:line so a large overload set can't overflow the per-tool cap.
3775	    const header = `**${matches.length} definitions named "${symbol}"**`;
3776	    if (!includeCode) {
3777	      const list = matches.map((n) => `- \`${n.name}\` (${n.kind}) — ${n.filePath}:${n.startLine}`);
3778	      return this.textResult(this.truncateOutput(
3779	        [header, '', 'Re-query with `includeCode: true` to get every body in one call — no need to pick one first.', '', ...list].join('\n'),
3780	      ));
3781	    }
3782	
3783	    const BODY_BUDGET = 12000; // leaves room under MAX_OUTPUT_LENGTH for the header + list
3784	    // The CHAR budget is the real limiter — keep the count cap high so a set of
3785	    // SHORT overloads (Alamofire's 10 `validate` variants, each a few lines) all
3786	    // render in full rather than relegating the one the agent wanted to a
3787	    // bodiless list. Only a set of many LARGE bodies hits the char budget first.
3788	    const HARD_CAP = 16;
3789	    const rendered: string[] = [];
3790	    const listed: Node[] = [];
3791	    let used = 0;
3792	    for (const n of matches) {
3793	      if (rendered.length >= HARD_CAP) { listed.push(n); continue; }
3794	      const section = await this.renderNodeSection(cg, n, true);
3795	      // Always emit the first; emit the rest only while within the char budget.
3796	      if (rendered.length === 0 || used + section.length <= BODY_BUDGET) {
3797	        rendered.push(section);
3798	        used += section.length;
3799	      } else {
3800	        listed.push(n);
3801	      }
3802	    }
3803	
3804	    const out: string[] = [
3805	      header,
3806	      `Returning ${rendered.length} in full${listed.length ? `; ${listed.length} more listed below` : ''} — pick the one you need (no Read required).`,
3807	      '',
3808	      rendered.join('\n\n---\n\n'),
3809	    ];
3810	    if (listed.length) {
3811	      const LIST_CAP = 20;
3812	      const shownList = listed.slice(0, LIST_CAP);
3813	      out.push(
3814	        '',
3815	        '**Other definitions**',
3816	        ...shownList.map((n) => `- \`${n.name}\` (${n.kind}) — ${n.filePath}:${n.startLine}`),
3817	      );
3818	      if (listed.length > LIST_CAP) out.push(`- … +${listed.length - LIST_CAP} more`);
3819	      out.push(
3820	        '',
3821	        `> Need one of these in full? Call codegraph_node again with \`file\` (e.g. \`"${listed[0]!.filePath.split('/').pop()}"\`) or \`line\` — do NOT Read it.`,
3822	      );
3823	    }
3824	    return this.textResult(this.truncateOutput(out.join('\n')));
3825	  }
