3827	  /**
3828	   * FILE READ MODE: resolve `fileArg` (path or basename) to an indexed file and
3829	   * read it like the Read tool — its current on-disk source with line numbers,
3830	   * narrowable with `offset`/`limit` exactly as Read's are — preceded by a
3831	   * one-line blast-radius header (which files depend on it). `symbolsOnly`
3832	   * returns just the structural map (symbols + dependents) instead of source.
3833	   *
3834	   * Parity goal: the numbered source block is byte-for-byte the shape Read
3835	   * returns (`<n>\t<line>`, no padding), so the agent treats it as a Read — only
3836	   * faster (served from the index) and with the blast radius attached. Security:
3837	   * yaml/properties files are summarized by key, never dumped (#383); reads go
3838	   * through validatePathWithinRoot (#527).
3839	   */
3840	  private async handleFileView(
3841	    cg: CodeGraph,
3842	    fileArg: string,
3843	    opts: { offset?: number; limit?: number; symbolsOnly?: boolean } = {},
3844	  ): Promise<ToolResult> {
3845	    const normalize = (p: string) => p.replace(/\\/g, '/').replace(/^(?:\.?\/+)+/, '').replace(/\/+$/, '');
3846	    const wantLower = normalize(fileArg).toLowerCase();
3847	    const allFiles = cg.getFiles();
3848	    if (allFiles.length === 0) return this.textResult('No files indexed. Run `codegraph index` first.');
3849	
3850	    let resolved = allFiles.find((f) => f.path.toLowerCase() === wantLower);
3851	    let candidates: typeof allFiles = [];
3852	    if (!resolved) {
3853	      candidates = allFiles.filter((f) => f.path.toLowerCase().endsWith('/' + wantLower));
3854	      if (candidates.length === 1) resolved = candidates[0];
3855	    }
3856	    if (!resolved && candidates.length === 0) {
3857	      candidates = allFiles.filter((f) => f.path.toLowerCase().includes(wantLower));
3858	      if (candidates.length === 1) resolved = candidates[0];
3859	    }
3860	    if (!resolved && candidates.length > 1) {
3861	      return this.textResult(
3862	        [`"${fileArg}" matches ${candidates.length} indexed files — pass a longer path:`, '',
3863	          ...candidates.slice(0, 25).map((f) => `- ${f.path}`)].join('\n'),
3864	      );
3865	    }
3866	    if (!resolved) {
3867	      return this.textResult(
3868	        `No indexed file matches "${fileArg}". Codegraph indexes source files; configs/docs it doesn't parse won't appear — Read those directly.`,
3869	      );
3870	    }
3871	
3872	    const filePath = resolved.path;
3873	    const nodes = cg.getNodesInFile(filePath)
3874	      .filter((n) => n.kind !== 'file' && n.kind !== 'import' && n.kind !== 'export')
3875	      .sort((a, b) => a.startLine - b.startLine);
3876	    const dependents = cg.getFileDependents(filePath);
3877	
3878	    // Compact, one-line blast radius (codegraph's value-add over a plain Read).
3879	    const depSummary = dependents.length
3880	      ? `used by ${dependents.length} file${dependents.length === 1 ? '' : 's'}: ${dependents.slice(0, 8).join(', ')}${dependents.length > 8 ? `, +${dependents.length - 8} more` : ''}`
3881	      : 'no other indexed file depends on it';
3882	
3883	    // Symbol-map renderer — for symbolsOnly, the config fallback, and read errors.
3884	    const symbolMap = (heading: string, limit = 200): string[] => {
3885	      const lines: string[] = [heading];
3886	      for (const n of nodes.slice(0, limit)) {
3887	        const sig = n.signature ? ` ${n.signature.replace(/\s+/g, ' ').trim()}` : '';
3888	        lines.push(`- \`${n.name}\` (${n.kind})${sig} — :${n.startLine}`);
3889	      }
3890	      if (nodes.length > limit) lines.push(`- … +${nodes.length - limit} more`);
3891	      return lines;
3892	    };
3893	
3894	    // symbolsOnly → the cheap structural overview, no source.
3895	    if (opts.symbolsOnly) {
3896	      const out = [`**${filePath}** — ${nodes.length} symbol${nodes.length === 1 ? '' : 's'}, ${depSummary}`, ''];
3897	      if (nodes.length) out.push(...symbolMap('**Symbols**'));
3898	      else out.push('_No indexed symbols in this file._');
3899	      out.push('', '> Drop `symbolsOnly` (or pass `offset`/`limit`) to read the source, like Read.');
3900	      return this.textResult(this.truncateOutput(out.join('\n')));
3901	    }
3902	
3903	    // SECURITY (#383): never dump a raw config/data file — a yaml/properties
3904	    // line is `key: <secret>`. Summarize by key and point to a real Read.
3905	    if (CONFIG_LEAF_LANGUAGES.has(resolved.language)) {
3906	      const out = [`**${filePath}** — configuration/data file, ${depSummary}`, ''];
3907	      if (nodes.length) out.push(...symbolMap('**Keys (values withheld for safety)**'));
3908	      out.push('', '> Values may be secrets, so codegraph indexes keys only. Read the file directly if you need a value.');
3909	      return this.textResult(this.truncateOutput(out.join('\n')));
3910	    }
3911	
3912	    // Read the current bytes from disk through the security chokepoint
3913	    // (validatePathWithinRoot: blocks `../` traversal and symlink escapes, #527).
3914	    const abs = validatePathWithinRoot(cg.getProjectRoot(), filePath);
3915	    let content: string | null = null;
3916	    if (abs) {
3917	      try { content = readFileSync(abs, 'utf-8'); } catch { content = null; }
3918	    }
3919	    if (content === null) {
3920	      const out = [`**${filePath}** — could not read from disk (it may have moved since indexing). ${depSummary}`, ''];
3921	      if (nodes.length) out.push(...symbolMap('**Symbols**'));
3922	      out.push('', `> Read \`${filePath}\` directly for its current content.`);
3923	      return this.textResult(this.truncateOutput(out.join('\n')));
3924	    }
3925	
3926	    // Split exactly as Read does — keep the trailing empty line a final newline
3927	    // produces (Read numbers it too), so line numbers line up byte-for-byte.
3928	    const fileLines = content.split('\n');
3929	    const total = fileLines.length;
3930	
3931	    // Read-parity windowing: `offset`/`limit` mean exactly what they do on Read
3932	    // (1-based start line; max line count). Default: the whole file, capped like
3933	    // Read at 2000 lines and bounded by a char budget that tracks explore's
3934	    // proven-safe ~38k response ceiling. Overflow is stated explicitly (Read
3935	    // paginates too) — never the silent 15k truncateOutput chop.
3936	    const CHAR_BUDGET = 38000;
3937	    const DEFAULT_LIMIT = 2000;
3938	    const offset = Math.max(1, opts.offset ?? 1);
3939	    if (offset > total) {
3940	      return this.textResult(`**${filePath}** has ${total} line${total === 1 ? '' : 's'} — offset ${offset} is past the end. ${depSummary}`);
3941	    }
3942	    const maxLines = Math.max(1, opts.limit ?? DEFAULT_LIMIT);
3943	    const start = offset - 1; // 0-based
3944	    const header = `**${filePath}** — ${total} lines, ${nodes.length} symbol${nodes.length === 1 ? '' : 's'} · ${depSummary}`;
3945	
3946	    // Numbered lines, byte-for-byte Read's shape: `<n>\t<line>`, no left-pad.
3947	    const numbered: string[] = [];
3948	    let used = header.length + 8;
3949	    let i = start;
3950	    for (; i < total && numbered.length < maxLines; i++) {
3951	      const ln = `${i + 1}\t${fileLines[i]}`;
3952	      if (used + ln.length + 1 > CHAR_BUDGET && numbered.length > 0) break;
3953	      numbered.push(ln);
3954	      used += ln.length + 1;
3955	    }
3956	    const shownEnd = start + numbered.length;
3957	    const complete = offset === 1 && shownEnd >= total;
3958	
3959	    const out: string[] = [header, '', ...numbered];
3960	    if (!complete) {
3961	      out.push(
3962	        '',
3963	        `(lines ${offset}–${shownEnd} of ${total} — pass \`offset\`/\`limit\` for another range, or \`codegraph_node <symbol>\` for one symbol in full)`,
3964	      );
3965	    }
3966	    // Self-bounded to CHAR_BUDGET — do NOT route through truncateOutput (15k).
3967	    return this.textResult(out.join('\n'));
3968	  }
