3970	  /** Render one symbol: details + (optional) body/outline + its caller/callee trail. */
3971	  private async renderNodeSection(cg: CodeGraph, node: Node, includeCode: boolean): Promise<string> {
3972	    let code: string | null = null;
3973	    let outline: string | null = null;
3974	    if (includeCode) {
3975	      // For container symbols (class/interface/struct/…), the full body is the
3976	      // sum of every method body — a wall of source. Return a structural outline
3977	      // (members + signatures + line numbers) instead; leaf symbols return their
3978	      // full body.
3979	      if (CONTAINER_NODE_KINDS.has(node.kind)) {
3980	        outline = this.buildContainerOutline(cg, node);
3981	      }
3982	      if (!outline) {
3983	        code = await cg.getCode(node.id);
3984	      }
3985	    }
3986	    return this.formatNodeDetails(node, code, outline) + this.formatTrail(cg, node);
3987	  }
