3989	  /**
3990	   * Build the "trail" for a symbol: its direct callees (what it calls) and
3991	   * callers (what calls it), each with file:line — so codegraph_node doubles as
3992	   * the structural Grep→Read→expand primitive: a spot PLUS where to go next.
3993	   * Capped to stay cheap. Walk the graph by calling codegraph_node on a trail
3994	   * entry; no Read needed for covered hops. Empty edges on a non-leaf often mean
3995	   * dynamic dispatch the static graph couldn't resolve — that absence is itself
3996	   * a signal (read that one hop) rather than a dead end.
3997	   */
3998	  private formatTrail(cg: CodeGraph, node: Node): string {
3999	    const TRAIL_CAP = 12;
4000	    const fmt = (e: { node: Node; edge: Edge }) => {
4001	      const base = `${e.node.name} (${e.node.filePath}:${e.node.startLine})`;
4002	      const synth = this.synthEdgeNote(e.edge);
4003	      return synth ? `${base} [${synth.compact}]` : base;
4004	    };
4005	    const collect = (edges: Array<{ node: Node; edge: Edge }>): Array<{ node: Node; edge: Edge }> => {
4006	      const seen = new Set<string>([node.id]);
4007	      const out: Array<{ node: Node; edge: Edge }> = [];
4008	      for (const e of edges) {
4009	        if (seen.has(e.node.id)) continue;
4010	        seen.add(e.node.id);
4011	        out.push(e);
4012	      }
4013	      return out;
4014	    };
4015	    const callees = collect(cg.getCallees(node.id));
4016	    const callers = collect(cg.getCallers(node.id));
4017	    if (callees.length === 0 && callers.length === 0) return '';
4018	    const lines: string[] = ['', '**Trail — codegraph_node any of these to follow it (no Read needed)**'];
4019	    if (callees.length > 0) {
4020	      lines.push(`**Calls →** ${callees.slice(0, TRAIL_CAP).map(fmt).join(', ')}${callees.length > TRAIL_CAP ? `, +${callees.length - TRAIL_CAP} more` : ''}`);
4021	    }
4022	    if (callers.length > 0) {
4023	      lines.push(`**Called by ←** ${callers.slice(0, TRAIL_CAP).map(fmt).join(', ')}${callers.length > TRAIL_CAP ? `, +${callers.length - TRAIL_CAP} more` : ''}`);
4024	    }
4025	    return lines.join('\n');
4026	  }
