4028	  /**
4029	   * Handle codegraph_status
4030	   */
4031	  private async handleStatus(args: Record<string, unknown>): Promise<ToolResult> {
4032	    let cg = this.getCodeGraph(args.projectPath as string | undefined);
4033	    // Same trick as withStalenessNotice — when an explicit projectPath
4034	    // resolves to the same project as the default session cg, prefer the
4035	    // default so getPendingFiles() (only populated by the default's watcher)
4036	    // is non-empty when there are pending edits.
4037	    if (this.cg && cg !== this.cg) {
4038	      try {
4039	        if (resolvePath(this.cg.getProjectRoot()) === resolvePath(cg.getProjectRoot())) {
4040	          cg = this.cg;
4041	        }
4042	      } catch { /* closed instance — leave as is */ }
4043	    }
4044	    const stats = cg.getStats();
4045	
4046	    // Warn when this index actually belongs to a different git working tree
4047	    // (e.g. the server resolved up from a nested worktree to the main checkout).
4048	    // Queries then reflect that tree's branch, not the worktree being edited.
4049	    // status shows the verbose, multi-line form; the read tools get the compact
4050	    // one-liner via withWorktreeNotice. Both share the cached detection.
4051	    const mismatch = this.worktreeMismatchFor(args.projectPath as string | undefined);
4052	
4053	    const lines: string[] = [
4054	      '**CodeGraph Status**',
4055	      '',
4056	    ];
4057	    if (mismatch) {
4058	      lines.push(`> ⚠ ${worktreeMismatchWarning(mismatch).replace(/\n/g, '\n> ')}`, '');
4059	    }
4060	    lines.push(
4061	      `**Files indexed:** ${stats.fileCount}`,
4062	      `**Total nodes:** ${stats.nodeCount}`,
4063	      `**Total edges:** ${stats.edgeCount}`,
4064	      `**Database size:** ${(stats.dbSizeBytes / 1024 / 1024).toFixed(2)} MB`,
4065	    );
4066	
4067	    // Surface the active SQLite backend (node:sqlite, Node's built-in real
4068	    // SQLite — full WAL + FTS5, no native build).
4069	    lines.push(`**Backend:** node:sqlite (Node built-in) — full WAL + FTS5`);
4070	
4071	    // Effective journal mode. 'wal' ⇒ concurrent reads never block on a writer;
4072	    // anything else ⇒ they can ("database is locked"). node:sqlite supports WAL
4073	    // everywhere, so a non-wal mode means the filesystem can't (network/
4074	    // virtualized mounts, WSL2 /mnt). See issue #238.
4075	    const journalMode = cg.getJournalMode();
4076	    if (journalMode === 'wal') {
4077	      lines.push(`**Journal mode:** wal (concurrent reads safe)`);
4078	    } else {
4079	      lines.push(
4080	        `**Journal mode:** ⚠ ${journalMode || 'unknown'} — WAL not active, so reads ` +
4081	        `can block on a concurrent write (WAL appears unsupported on this filesystem)`
4082	      );
4083	    }
4084	
4085	    // A newer release exists (#1243) — status is where users and agents look
4086	    // when something seems off, so surface the drift here too. Cheap memoized
4087	    // cache read; absent entirely when up to date or opted out.
4088	    const updateNotice = getUpdateNotice();
4089	    if (updateNotice) {
4090	      lines.push(`**Update available:** ${updateNotice}`);
4091	    }
4092	
4093	    // Non-zero at rest means a resolution pass was interrupted mid-run, so
4094	    // some files' call/impact edges are missing until the next sync sweeps
4095	    // the leftovers (#1187). Surface it — an agent trusting an incomplete
4096	    // blast radius is worse than one that knows to re-sync.
4097	    const pendingRefs = cg.getPendingReferenceCount();
4098	    if (pendingRefs > 0) {
4099	      lines.push(
4100	        `**Pending resolution:** ⚠ ${pendingRefs} references from an interrupted ` +
4101	        `index run — some caller/impact edges are missing until the next sync ` +
4102	        `(any file change triggers it, or run \`codegraph sync\`)`
4103	      );
4104	    }
4105	
4106	    lines.push('', '**Nodes by Kind:**');
4107	
4108	    for (const [kind, count] of Object.entries(stats.nodesByKind)) {
4109	      if ((count as number) > 0) {
4110	        lines.push(`- ${kind}: ${count}`);
4111	      }
4112	    }
4113	
4114	    lines.push('', '**Languages:**');
4115	    for (const [lang, count] of Object.entries(stats.filesByLanguage)) {
4116	      if ((count as number) > 0) {
4117	        lines.push(`- ${lang}: ${count}`);
4118	      }
4119	    }
4120	
4121	    // Whole-index degradation (#876): when live watching has permanently
4122	    // stopped, getPendingFiles() is empty (so no "Pending sync" section below)
4123	    // but the index is frozen — call that out explicitly here, the one place an
4124	    // agent asks "is the index caught up?".
4125	    if (cg.isWatcherDegraded()) {
4126	      lines.push(
4127	        '',
4128	        '**Auto-sync disabled:**',
4129	        `- ${cg.getWatcherDegradedReason() ?? 'live file watching stopped'}`,
4130	        '- The index is frozen; Read files directly for current content.'
4131	      );
4132	    }
4133	
4134	    // Per-file freshness — the inverse of the auto-prepended staleness banner
4135	    // (issue #403). Surfacing it inside `status` gives the agent a single
4136	    // place to ask "is the index caught up?" rather than inferring from
4137	    // banners on other tool calls.
4138	    const pending = cg.getPendingFiles();
4139	    if (pending.length > 0) {
4140	      lines.push('', '**Pending sync:**');
4141	      const now = Date.now();
4142	      for (const p of pending) {
4143	        const ageMs = Math.max(0, now - p.lastSeenMs);
4144	        const label = p.indexing ? 'indexing in progress' : 'pending sync';
4145	        lines.push(`- ${p.path} (edited ${ageMs}ms ago, ${label})`);
4146	      }
4147	    }
4148	
4149	    return this.textResult(lines.join('\n'));
4150	  }
