4152	  /**
4153	   * Handle codegraph_files - get project file structure from the index
4154	   */
4155	  private async handleFiles(args: Record<string, unknown>): Promise<ToolResult> {
4156	    const cg = this.getCodeGraph(args.projectPath as string | undefined);
4157	    const pathFilter = args.path as string | undefined;
4158	    const pattern = args.pattern as string | undefined;
4159	    const format = (args.format as 'tree' | 'flat' | 'grouped') || 'tree';
4160	    const includeMetadata = args.includeMetadata !== false;
4161	    const maxDepth = args.maxDepth != null ? clamp(args.maxDepth as number, 1, 20) : undefined;
4162	
4163	    // Get all files from the index
4164	    const allFiles = cg.getFiles();
4165	
4166	    if (allFiles.length === 0) {
4167	      return this.textResult('No files indexed. Run `codegraph index` first.');
4168	    }
4169	
4170	    // Filter by path prefix. Stored paths are project-relative POSIX (e.g.
4171	    // "src/foo.ts"), but agents commonly pass project-root variants like "/",
4172	    // ".", "./", "" or Windows-style "src\foo" — and prefixes with leading
4173	    // "/", "./" or "\". Normalize all of those before matching so the agent
4174	    // gets results instead of falling back to Read/Glob (see #426).
4175	    const normalizedFilter = pathFilter
4176	      ? pathFilter
4177	          .replace(/\\/g, '/')
4178	          .replace(/^(?:\.?\/+)+/, '')
4179	          .replace(/^\.$/, '')
4180	          .replace(/\/+$/, '')
4181	      : '';
4182	    let files = normalizedFilter
4183	      ? allFiles.filter(f => f.path === normalizedFilter || f.path.startsWith(normalizedFilter + '/'))
4184	      : allFiles;
4185	
4186	    // Filter by glob pattern
4187	    if (pattern) {
4188	      const regex = this.globToRegex(pattern);
4189	      files = files.filter(f => regex.test(f.path));
4190	    }
4191	
4192	    if (files.length === 0) {
4193	      return this.textResult(`No files found matching the criteria.`);
4194	    }
4195	
4196	    // Format output
4197	    let output: string;
4198	    switch (format) {
4199	      case 'flat':
4200	        output = this.formatFilesFlat(files, includeMetadata);
4201	        break;
4202	      case 'grouped':
4203	        output = this.formatFilesGrouped(files, includeMetadata);
4204	        break;
4205	      case 'tree':
4206	      default:
4207	        output = this.formatFilesTree(files, includeMetadata, maxDepth);
4208	        break;
4209	    }
4210	
4211	    return this.textResult(this.truncateOutput(output));
4212	  }
