4214	  /**
4215	   * Convert glob pattern to regex
4216	   */
4217	  private globToRegex(pattern: string): RegExp {
4218	    const escaped = pattern
4219	      .replace(/[.+^${}()|[\]\\]/g, '\\$&')  // Escape special regex chars except * and ?
4220	      .replace(/\*\*/g, '{{GLOBSTAR}}')       // Temp placeholder for **
4221	      .replace(/\*/g, '[^/]*')                // * matches anything except /
4222	      .replace(/\?/g, '[^/]')                 // ? matches single char except /
4223	      .replace(/\{\{GLOBSTAR\}\}/g, '.*');    // ** matches anything including /
4224	    return new RegExp(escaped);
4225	  }
