4228	   * Format files as a flat list
4229	   */
4230	  private formatFilesFlat(files: { path: string; language: string; nodeCount: number }[], includeMetadata: boolean): string {
4231	    const lines: string[] = [`**Files (${files.length})**`, ''];
4232	
4233	    for (const file of files.sort((a, b) => a.path.localeCompare(b.path))) {
4234	      if (includeMetadata) {
4235	        lines.push(`- ${file.path} (${file.language}, ${file.nodeCount} symbols)`);
4236	      } else {
4237	        lines.push(`- ${file.path}`);
4238	      }
4239	    }
4240	
4241	    return lines.join('\n');
