4244	  /**
4245	   * Format files grouped by language
4246	   */
4247	  private formatFilesGrouped(files: { path: string; language: string; nodeCount: number }[], includeMetadata: boolean): string {
4248	    const byLang = new Map<string, typeof files>();
4249	
4250	    for (const file of files) {
4251	      const existing = byLang.get(file.language) || [];
4252	      existing.push(file);
4253	      byLang.set(file.language, existing);
4254	    }
4255	
4256	    const lines: string[] = [`**Files by Language (${files.length} total)**`, ''];
4257	
4258	    // Sort languages by file count (descending)
4259	    const sortedLangs = [...byLang.entries()].sort((a, b) => b[1].length - a[1].length);
4260	
4261	    for (const [lang, langFiles] of sortedLangs) {
4262	      lines.push(`**${lang} (${langFiles.length})**`);
4263	      for (const file of langFiles.sort((a, b) => a.path.localeCompare(b.path))) {
4264	        if (includeMetadata) {
4265	          lines.push(`- ${file.path} (${file.nodeCount} symbols)`);
4266	        } else {
4267	          lines.push(`- ${file.path}`);
4268	        }
4269	      }
4270	      lines.push('');
4271	    }
4272	
4273	    return lines.join('\n');
4274	  }
