4276	  /**
4277	   * Format files as a tree structure
4278	   */
4279	  private formatFilesTree(
4280	    files: { path: string; language: string; nodeCount: number }[],
4281	    includeMetadata: boolean,
4282	    maxDepth?: number
4283	  ): string {
4284	    // Build tree structure
4285	    interface TreeNode {
4286	      name: string;
4287	      children: Map<string, TreeNode>;
4288	      file?: { language: string; nodeCount: number };
4289	    }
4290	
4291	    const root: TreeNode = { name: '', children: new Map() };
4292	
4293	    for (const file of files) {
4294	      const parts = file.path.split('/');
4295	      let current = root;
4296	
4297	      for (let i = 0; i < parts.length; i++) {
4298	        const part = parts[i];
4299	        if (!part) continue;
4300	
4301	        if (!current.children.has(part)) {
4302	          current.children.set(part, { name: part, children: new Map() });
4303	        }
4304	        current = current.children.get(part)!;
4305	
4306	        // If this is the last part, it's a file
4307	        if (i === parts.length - 1) {
4308	          current.file = { language: file.language, nodeCount: file.nodeCount };
4309	        }
4310	      }
4311	    }
4312	
4313	    // Render tree
4314	    const lines: string[] = [`**Project Structure (${files.length} files)**`, ''];
4315	
4316	    const renderNode = (node: TreeNode, prefix: string, isLast: boolean, depth: number): void => {
4317	      if (maxDepth !== undefined && depth > maxDepth) return;
4318	
4319	      const connector = isLast ? '└── ' : '├── ';
4320	      const childPrefix = isLast ? '    ' : '│   ';
4321	
4322	      if (node.name) {
4323	        let line = prefix + connector + node.name;
4324	        if (node.file && includeMetadata) {
4325	          line += ` (${node.file.language}, ${node.file.nodeCount} symbols)`;
4326	        }
4327	        lines.push(line);
4328	      }
4329	
4330	      const children = [...node.children.values()];
4331	      // Sort: directories first, then files, both alphabetically
4332	      children.sort((a, b) => {
4333	        const aIsDir = a.children.size > 0 && !a.file;
4334	        const bIsDir = b.children.size > 0 && !b.file;
4335	        if (aIsDir !== bIsDir) return aIsDir ? -1 : 1;
4336	        return a.name.localeCompare(b.name);
4337	      });
4338	
4339	      for (let i = 0; i < children.length; i++) {
4340	        const child = children[i]!;
4341	        const nextPrefix = node.name ? prefix + childPrefix : prefix;
4342	        renderNode(child, nextPrefix, i === children.length - 1, depth + 1);
4343	      }
4344	    };
4345	
4346	    renderNode(root, '', true, 0);
4347	
4348	    return lines.join('\n');
4349	  }
