4351	  // =========================================================================
4352	  // Symbol resolution helpers
4353	  // =========================================================================
4354	
4355	  /**
4356	   * Find a symbol by name, handling disambiguation when multiple matches exist.
4357	   * Returns the best match and a note about alternatives if any.
4358	   */
4359	  /**
4360	   * Check if a node matches a symbol query.
4361	   *
4362	   * Accepts simple names (`run`) and three flavors of qualifier:
4363	   *   - dotted     `Session.request`         (TS/JS/Python)
4364	   *   - colon-pair `stage_apply::run`        (Rust, C++, Ruby)
4365	   *   - slash      `configurator/stage_apply` (path-ish)
4366	   *
4367	   * Multi-level qualifiers compose: `crate::configurator::stage_apply::run`
4368	   * works. Rust path prefixes (`crate`, `super`, `self`) are stripped so
4369	   * the canonical `crate::module::symbol` form resolves.
4370	   *
4371	   * Resolution order, last part must always equal `node.name`:
4372	   *   1. Suffix-match against `qualifiedName` (handles class-scoped methods
4373	   *      where the extractor builds the qualified name from the AST stack)
4374	   *   2. File-path containment (handles file-derived modules in Rust/
4375	   *      Python — `stage_apply::run` matches a `run` in `stage_apply.rs`)
4376	   */
4377	  private matchesSymbol(node: Node, symbol: string): boolean {
4378	    // Simple name match
4379	    if (node.name === symbol) return true;
4380	    // File basename match (e.g., "product-card" matches "product-card.liquid")
4381	    if (node.kind === 'file' && node.name.replace(/\.[^.]+$/, '') === symbol) return true;
4382	
4383	    // Qualified-name lookups: split on any supported separator. `\w` keeps
4384	    // identifier chars (incl. `_`) intact; everything else is treated as
4385	    // a separator we tolerate.
4386	    if (!/[.\/]|::/.test(symbol)) return false;
4387	    const parts = symbol.split(/::|[./]/).filter((p) => p.length > 0);
4388	    if (parts.length < 2) return false;
4389	
4390	    const lastPart = parts[parts.length - 1]!;
4391	    if (node.name !== lastPart) return false;
4392	
4393	    // Stage 1: qualified-name suffix match. The extractor joins the
4394	    // semantic hierarchy with `::`, so `Session.request` and
4395	    // `Session::request` both become `Session::request` here.
4396	    const colonSuffix = parts.join('::');
4397	    if (node.qualifiedName.includes(colonSuffix)) return true;
4398	
4399	    // Stage 2: file-path containment. Rust modules and Python packages
4400	    // are not in `qualifiedName` — they're encoded in the file path. So
4401	    // `stage_apply::run` matches a `run` in any file whose path
4402	    // contains a `stage_apply` segment (with or without an extension).
4403	    //
4404	    // Filter out Rust path prefixes that have no file-system equivalent.
4405	    const containerHints = parts.slice(0, -1).filter((p) => !RUST_PATH_PREFIXES.has(p));
4406	    if (containerHints.length === 0) return false;
4407	
4408	    const segments = node.filePath.split('/').filter((s) => s.length > 0);
4409	    return containerHints.every((hint) =>
4410	      segments.some((seg) => seg === hint || seg.replace(/\.[^.]+$/, '') === hint)
4411	    );
4412	  }
4413	
4414	  /**
4415	   * Find ALL definitions matching a name, ranked, so codegraph_node can return
4416	   * every overload instead of guessing one (the wrong guess → a Read). Keepers
4417	   * rank before generated stubs (.pb.go etc.); stable within a group preserves
4418	   * FTS order. Returns [] when nothing matches; a qualified lookup that finds no
4419	   * exact match returns [] rather than a misleading fuzzy file hit (#173); a
4420	   * bare name with no exact match falls back to the single top fuzzy result.
4421	   */
4422	  private findSymbolMatches(cg: CodeGraph, symbol: string): Node[] {
4423	    const isQualified = /[.\/]|::/.test(symbol);
4424	
4425	    // For a bare name, enumerate EVERY exact-name definition via the direct index
4426	    // (not FTS, which caps + ranks): tokio's `poll` has 50+ defs and the one the
4427	    // caller wants (`Harness::poll` at harness.rs:153) ranks below any search cut,
4428	    // so it could be neither rendered nor pinned by the file/line disambiguator —
4429	    // and the agent Read it. With the full set, the multi-overload render + the
4430	    // file/line filter can both reach it.
4431	    if (!isQualified) {
4432	      const exact = cg.getNodesByName(symbol);
4433	      if (exact.length > 0) {
4434	        return [...exact].sort((a, b) => (isGeneratedFile(a.filePath) ? 1 : 0) - (isGeneratedFile(b.filePath) ? 1 : 0));
4435	      }
4436	      // No exact match — use the single top fuzzy result (e.g. a file basename).
4437	      const fuzzy = cg.searchNodes(symbol, { limit: 10 });
4438	      return fuzzy[0] ? [fuzzy[0].node] : [];
4439	    }
4440	
4441	    // Qualified lookup (`Session.request`, `stage_apply::run`): FTS + matchesSymbol.
4442	    const limit = 50;
4443	    let results = cg.searchNodes(symbol, { limit });
4444	
4445	    // FTS strips colons, so `stage_apply::run` searches the literal
4446	    // `stage_applyrun` and finds nothing. Re-search by the bare last part and
4447	    // let `matchesSymbol` filter by qualifier.
4448	    if (isQualified && results.length === 0) {
4449	      const tail = lastQualifierPart(symbol);
4450	      if (tail && tail !== symbol) results = cg.searchNodes(tail, { limit });
4451	    }
4452	
4453	    if (results.length === 0) return [];
4454	
4455	    const exactMatches = results.filter((r) => this.matchesSymbol(r.node, symbol));
4456	    if (exactMatches.length === 0) {
4457	      // No exact match — a qualified lookup must not fall back to a fuzzy file
4458	      // hit (#173); a bare name may use the single top fuzzy result.
4459	      return isQualified ? [] : results[0] ? [results[0].node] : [];
4460	    }
4461	
4462	    // Down-rank generated files (.pb.go, .pulsar.go, _grpc.pb.go, …) so a flow
4463	    // query prefers the keeper implementation over the protobuf-generated stub.
4464	    return [...exactMatches]
4465	      .sort((a, b) => (isGeneratedFile(a.node.filePath) ? 1 : 0) - (isGeneratedFile(b.node.filePath) ? 1 : 0))
4466	      .map((r) => r.node);
4467	  }
