4469	  /**
4470	   * Find ALL symbols matching a name. Used by callers/callees/impact to aggregate
4471	   * results across all matching symbols (e.g., multiple classes with an `execute` method).
4472	   */
4473	  private findAllSymbols(cg: CodeGraph, symbol: string): { nodes: Node[]; note: string } {
4474	    // Nix option paths: the declaration is stored as `options.<path>` and
4475	    // config writes carry longer/quoted tails (`<path>."git/config".text`),
4476	    // so a dotted option token (`xdg.configFile`, `launchd.user.agents`) has
4477	    // no exact-name node and would degrade to bare-tail FTS soup — burying
4478	    // the declaration hub the nix-option-path edges hang off. Resolve the
4479	    // convention directly: declaration first, then the exact write, then a
4480	    // capped prefix scan of write sites. Three index hits; non-nix graphs
4481	    // fall straight through.
4482	    if (/^[a-z][\w'-]*(?:\.[\w'-]+)+$/.test(symbol)) {
4483	      const optionHits = [
4484	        ...cg.getNodesByName(`options.${symbol}`),
4485	        ...cg.getNodesByName(symbol),
4486	        ...cg.getNodesByNamePrefix(`${symbol}.`, 12),
4487	      ].filter((n) => n.language === 'nix');
4488	      if (optionHits.length > 0) {
4489	        const seen = new Set<string>();
4490	        const nodes = optionHits.filter((n) => !seen.has(n.id) && !!seen.add(n.id)).slice(0, 10);
4491	        return { nodes, note: '' };
4492	      }
4493	    }
4494	    let results = cg.searchNodes(symbol, { limit: 50 });
4495	
4496	    // Mirror the fallback in `findSymbol` for qualified queries — FTS
4497	    // strips colons, so a module-qualified lookup needs a second pass
4498	    // by the bare last part.
4499	    if (results.length === 0 && /[.\/]|::/.test(symbol)) {
4500	      const tail = lastQualifierPart(symbol);
4501	      if (tail && tail !== symbol) results = cg.searchNodes(tail, { limit: 50 });
4502	    }
4503	
4504	    if (results.length === 0) {
4505	      return { nodes: [], note: '' };
4506	    }
4507	
4508	    const exactMatches = results.filter(r => this.matchesSymbol(r.node, symbol));
4509	
4510	    if (exactMatches.length <= 1) {
4511	      const node = exactMatches[0]?.node ?? results[0]!.node;
4512	      return { nodes: [node], note: '' };
4513	    }
4514	
4515	    // Same generated-file down-rank as findSymbol — keeps callers/callees
4516	    // /impact aggregation aligned (a query against "Send" returns the
4517	    // hand-written implementations before the protobuf scaffold).
4518	    const ranked = [...exactMatches].sort((a, b) => {
4519	      const aGen = isGeneratedFile(a.node.filePath) ? 1 : 0;
4520	      const bGen = isGeneratedFile(b.node.filePath) ? 1 : 0;
4521	      return aGen - bGen;
4522	    });
4523	
4524	    const locations = ranked.map(r =>
4525	      `${r.node.kind} at ${r.node.filePath}:${r.node.startLine}`
4526	    );
4527	    const note = `\n\n> **Note:** Aggregated results across ${ranked.length} symbols named "${symbol}": ${locations.join(', ')}`;
4528	    return { nodes: ranked.map(r => r.node), note };
4529	  }
