4531	  /**
4532	   * Truncate output if it exceeds the maximum length
4533	   */
4534	  private truncateOutput(text: string): string {
4535	    if (text.length <= MAX_OUTPUT_LENGTH) return text;
4536	    const truncated = text.slice(0, MAX_OUTPUT_LENGTH);
4537	    const lastNewline = truncated.lastIndexOf('\n');
4538	    const cutPoint = lastNewline > MAX_OUTPUT_LENGTH * 0.8 ? lastNewline : MAX_OUTPUT_LENGTH;
4539	    return truncated.slice(0, cutPoint) + '\n\n... (output truncated)';
4540	  }
