4562	  private formatNodeList(nodes: Node[], title: string, labels?: Map<string, string>): string {
4563	    const lines: string[] = [`**${title} (${nodes.length} found)**`, ''];
4564	
4565	    for (const node of nodes) {
4566	      const location = node.startLine ? `:${node.startLine}` : '';
4567	      // Compact: just name, kind, location — plus the relationship when it
4568	      // isn't a plain call (callback registration, instantiation, …).
4569	      const label = labels?.get(node.id);
4570	      lines.push(
4571	        `- ${node.name} (${node.kind}) - ${node.filePath}${location}${label ? ` — via ${label}` : ''}`
