4578	  /**
4579	   * Relationship label for a non-`calls` edge in callers/callees lists. A
4580	   * function-as-value edge (#756) is the high-signal one: `callers(cb)`
4581	   * showing "via callback registration" tells the agent this is where the
4582	   * callback is WIRED, not where it's invoked.
4583	   */
4584	  private edgeLabel(edge: Edge): string | null {
4585	    if (edge.kind === 'calls') return null;
4586	    if (edge.metadata?.fnRef === true) return 'callback registration';
4587	    if (edge.kind === 'instantiates') return 'instantiation';
4588	    if (edge.kind === 'imports') return 'import';
4589	    if (edge.kind === 'references') return 'reference';
4590	    return edge.kind;
4591	  }
